export type RuleEntry = { id: string; name: string; tag: string; text: string };

export const GLOSSARY_2024: RuleEntry[] = [
  {"id": "glossary_ability_check", "name": "Ability Check", "tag": "", "text": "An ability check is a D20 Test that represents using one of the six abilities--or a specific skill associated with an ability--to overcome a challenge. See also \"Playing the Game\" (\"D20 Tests\" and \"Proficiency\")."},
  {"id": "glossary_ability_score_and_modifier", "name": "Ability Score and Modifier", "tag": "", "text": "A creature has six ability scores--Strength, Dexterity, Constitution, Intelligence, Wisdom, and Charisma--each of which has a corresponding modifier. Add the modifier when you make a D20 Test with the corresponding ability or when a rule asks you to do so. See also \"Playing the Game\" (\"The Six Abilities\")."},
  {"id": "glossary_action", "name": "Action", "tag": "", "text": "On your turn, you can take one action. Choose which action to take from those below or from the special actions provided by your features. See also \"Playing the Game\" (\"Actions\"). These actions are defined elsewhere in this glossary:\n\nAttack Dash Disengage\n\nDodge Help Hide\n\nInfluence Magic Ready\n\nSearch Study Utilize"},
  {"id": "glossary_advantage", "name": "Advantage", "tag": "", "text": "If you have Advantage on a D20 Test, roll two d20s, and use the higher roll. A roll can't be affected by more than one Advantage, and Advantage and Disadvantage on the same roll cancel each other. See also \"Playing the Game\" (\"D20 Tests\")."},
  {"id": "glossary_adventure", "name": "Adventure", "tag": "", "text": "An adventure is a series of encounters. A story emerges through playing them. See also \"Encounter.\""},
  {"id": "glossary_alignment", "name": "Alignment", "tag": "", "text": "A creature's alignment broadly describes its ethical attitudes and ideals. Alignment is a combination of two factors: one identifies morality (good, evil, or neutral), and the other describes attitudes toward order (lawful, chaotic, or neutral). These factors allow for nine possible combinations, such as Lawful Good and Neutral Evil. See also \"Character Creation\" (\"Create Your Character\")."},
  {"id": "glossary_ally", "name": "Ally", "tag": "", "text": "A creature is your ally if it is a member of your adventuring party, your friend, on your side in combat, or a creature that the rules or the GM designates as your ally."},
  {"id": "glossary_area_of_effect", "name": "Area of Effect", "tag": "", "text": "The descriptions of many spells and other features specify that they have an area of effect, which typically has one of six shapes. These shapes are defined elsewhere in this glossary:\n\nCone Cube\n\nCylinder Emanation\n\nLine Sphere\n\nAn area of effect has a point of origin, a location from which the effect's energy erupts. The rules for each shape specify how to position its point of origin. If all straight lines extending from the point of origin to a location in the area of effect are blocked, that location isn't included in the area of effect. To block a line, an obstruction must provide Total Cover. See also \"Cover.\"\n\nIf the creator of an area of effect places it at an unseen point and an obstruction--such as a wall-- is between the creator and that point, the point of origin comes into being on the near side of the obstruction."},
  {"id": "glossary_armor_class", "name": "Armor Class", "tag": "", "text": "An Armor Class (AC) is the target number for an attack roll. AC represents how difficult it is to hit a target.\n\nYour base AC calculation is 10 plus your Dexterity modifier. If a rule gives you another base AC calculation, you choose which calculation to use; you can't use more than one. See also \"Attack Roll.\""},
  {"id": "glossary_armor_training", "name": "Armor Training", "tag": "", "text": "Armor training allows you to use armor of a certain category without the following drawbacks. If you wear Light, Medium, or Heavy armor and lack training with it, you have Disadvantage on any D20 Test that involves Strength or Dexterity, and you can't cast spells. If you use a Shield and lack training with it, you don't gain its AC bonus. See also \"Disadvantage\" and \"Equipment\" (\"Armor\")."},
  {"id": "glossary_attack", "name": "Attack", "tag": "Action", "text": "When you take the Attack action, you can make one attack roll with a weapon or an Unarmed Strike.\n\nEquipping and Unequipping Weapons. You can either equip or unequip one weapon when you make an attack as part of this action. You do so either before or after the attack. If you equip a weapon before an attack, you don't need to use it for that attack. Equipping a weapon includes drawing it from a sheath or picking it up. Unequipping a weapon includes sheathing, stowing, or dropping it.\n\nMoving between Attacks. If you move on your turn and have a feature, such as Extra Attack, that gives you more than one attack as part of the Attack action, you can use some or all of that movement to move between those attacks.\n\nAttack Roll\n\nAn attack roll is a D20 Test that represents making an attack with a weapon, an Unarmed Strike, or a spell. See also \"Playing the Game\" (\"D20 Tests\")."},
  {"id": "glossary_attitude", "name": "Attitude", "tag": "", "text": "A monster has a starting attitude toward a player character: Friendly, Hostile, or Indifferent. See also \"Friendly,\" \"Hostile,\" \"Indifferent,\" and \"Influence.\""},
  {"id": "glossary_attunement", "name": "Attunement", "tag": "", "text": "Some magic items require a creature to form a bond--called Attunement--with them before the creature can use an item's magical properties. A creature can have Attunement with no more than three magic items at a time. See also \"Equipment\" (\"Magic Items\")."},
  {"id": "glossary_blinded", "name": "Blinded", "tag": "Condition", "text": "While you have the Blinded condition, you experience the following effects.\n\nCan't See. You can't see and automatically fail any ability check that requires sight.\n\nAttacks Affected. Attack rolls against you have Advantage, and your attack rolls have Disadvantage."},
  {"id": "glossary_blindsight", "name": "Blindsight", "tag": "", "text": "If you have Blindsight, you can see within a specific range without relying on physical sight. Within that range, you can see anything that isn't behind Total Cover even if you have the Blinded condition or are in Darkness. Moreover, in that range, you can see something that has the Invisible condition."},
  {"id": "glossary_bloodied", "name": "Bloodied", "tag": "", "text": "A creature is Bloodied while it has half its Hit Points or fewer remaining."},
  {"id": "glossary_bonus_action", "name": "Bonus Action", "tag": "", "text": "A Bonus Action is a special action that you can take on the same turn that you take an action. You can't take more than one Bonus Action on a turn, and you have a Bonus Action to take only if a rule explicitly says so. See also \"Playing the Game\" (\"Actions\")."},
  {"id": "glossary_breaking_objects", "name": "Breaking Objects", "tag": "", "text": "Objects can be harmed by attacks and by some spells, using the rules below. If an object is exceedingly fragile, the GM may allow a creature to break it automatically with the Attack or Utilize action.\n\nArmor Class. The Object Armor Class table suggests ACs for various substances."},
  {"id": "glossary_object_armor_class", "name": "Object Armor Class", "tag": "", "text": "AC Substance 11 Cloth, paper, rope 13 Crystal, glass, ice 15 Wood 17 Stone\n\nAC Substance 19 Iron, steel 21 Mithral 23 Adamantine\n\nHit Points. An object is destroyed when it has 0 Hit Points. The Object Hit Points table suggests Hit Points for fragile and resilient objects that are Large or smaller. To track Hit Points for a Huge or Gargantuan object, divide it into Large or smaller sections, and track each section's Hit Points separately. The GM determines whether destroying part of an object causes the whole thing to collapse."},
  {"id": "glossary_object_hit_points", "name": "Object Hit Points", "tag": "", "text": "Size Tiny (bottle, lock) Small (chest, lute) Medium (barrel, chandelier) Large (cart, dining table)\n\nFragile 2 (1d4) 3 (1d6) 4 (1d8) 5 (1d10)\n\nResilient 5 (2d4) 10 (3d6) 18 (4d8) 27 (5d10)\n\nDamage Types and Objects. Objects have Immunity to Poison and Psychic damage. The GM might decide that some damage types are more or less effective against an object. For example, Bludgeoning damage works well for smashing things but not for cutting. Paper or cloth objects might have Vulnerability to Fire damage.\n\nDamage Threshold. Big objects, such as castle walls, often have extra resilience represented by a damage threshold. See also \"Damage Threshold.\"\n\nNo Ability Scores. An object lacks ability scores unless a rule assigns scores to the object. Without ability scores, an object can't make ability checks, and it fails all saving throws."},
  {"id": "glossary_bright_light", "name": "Bright Light", "tag": "", "text": "Bright Light is normal illumination. See also \"Playing the Game\" (\"Exploration\")."},
  {"id": "glossary_burning", "name": "Burning", "tag": "Hazard", "text": "A burning creature or object takes 1d4 Fire damage at the start of each of its turns. As an action, you can extinguish fire on yourself by giving yourself the Prone condition and rolling on the ground. The fire also goes out if it is doused, submerged, or suffocated."},
  {"id": "glossary_burrow_speed", "name": "Burrow Speed", "tag": "", "text": "A creature that has a Burrow Speed can use that speed to move through sand, earth, mud, or ice. The creature can't burrow through solid rock unless the creature has a trait that allows it to do so. See also \"Speed.\""},
  {"id": "glossary_campaign", "name": "Campaign", "tag": "", "text": "A campaign is a series of adventures. See also \"Adventure.\""},
  {"id": "glossary_cantrip", "name": "Cantrip", "tag": "", "text": "A cantrip is a level 0 spell, which is cast without a spell slot. See also \"Spells.\""},
  {"id": "glossary_carrying_capacity", "name": "Carrying Capacity", "tag": "", "text": "Your size and Strength score determine the maximum weight in pounds that you can carry, as shown in the Carrying Capacity table. The table also shows the maximum weight you can drag, lift, or push.\n\nWhile dragging, lifting, or pushing weight in excess of the maximum weight you can carry, your Speed can be no more than 5 feet.\n\nCarrying Capacity\n\nCreature Size Carry\n\nTiny\n\nStr. × 7.5 lb.\n\nSmall/Medium Str. × 15 lb.\n\nLarge\n\nStr. × 30 lb.\n\nHuge\n\nStr. × 60 lb.\n\nGargantuan\n\nStr. × 120 lb.\n\nDrag/Lift/Push Str. × 15 lb. Str. × 30 lb. Str. × 60 lb. Str. × 120 lb. Str. × 240 lb."},
  {"id": "glossary_challenge_rating", "name": "Challenge Rating", "tag": "", "text": "Challenge Rating (CR) summarizes the threat a monster poses to a group of four player characters. Compare a monster's CR to the characters' level. If the CR is higher, the monster is likely a danger. If the CR is lower, the monster likely poses little threat. But circumstances and the number of player characters can significantly alter how threatening a monster is in actual play. \"Gameplay Toolbox\" (\"Combat Encounters\") provides guidance to the GM on using CR while planning potential combat encounters. See also \"Stat Block.\""},
  {"id": "glossary_character_sheet", "name": "Character Sheet", "tag": "", "text": "A character sheet is a paper or digital record that you use to track your character's information. See also \"Character Creation.\""},
  {"id": "glossary_charmed", "name": "Charmed", "tag": "Condition", "text": "While you have the Charmed condition, you experience the following effects.\n\nCan't Harm the Charmer. You can't attack the charmer or target the charmer with damaging abilities or magical effects.\n\nSocial Advantage. The charmer has Advantage on any ability check to interact with you socially."},
  {"id": "glossary_climbing", "name": "Climbing", "tag": "", "text": "While you're climbing, each foot of movement costs 1 extra foot (2 extra feet in Difficult Terrain). You ignore this extra cost if you have a Climb Speed and use it to climb.\n\nAt the GM's option, climbing a slippery surface or one with few handholds might require a successful DC 15 Strength (Athletics) check."},
  {"id": "glossary_climb_speed", "name": "Climb Speed", "tag": "", "text": "A Climb Speed can be used in place of Speed to traverse a vertical surface without expending the extra movement normally associated with climbing. See also \"Climbing\" and \"Speed.\""},
  {"id": "glossary_concentration", "name": "Concentration", "tag": "", "text": "Some spells and other effects require Concentration to remain active, as specified in their descriptions. If the effect's creator loses Concentration, the effect ends. If the effect has a maximum duration, the effect's description specifies how long the creator can concentrate on it: up to 1 minute, 1 hour, or some other duration. The creator can end Concentration at any time (no action required). The following factors break Concentration.\n\nAnother Concentration Effect. You lose Concentration on an effect the moment you start casting a spell that requires Concentration or activate another effect that requires Concentration.\n\nDamage. If you take damage, you must succeed on a Constitution saving throw to maintain Concentration. The DC equals 10 or half the damage taken (round down), whichever number is higher, up to a maximum DC of 30.\n\nIncapacitated or Dead. Your Concentration ends if you have the Incapacitated condition or you die."},
  {"id": "glossary_condition", "name": "Condition", "tag": "", "text": "A condition is a temporary game state. The definition of a condition says how it affects its recipient, and various rules define how to end a condition. This glossary defines these conditions:\n\nBlinded Charmed Deafened Exhaustion Frightened\n\nGrappled Incapacitated Invisible Paralyzed Petrified\n\nPoisoned Prone Restrained Stunned Unconscious\n\nA condition doesn't stack with itself; a recipient either has a condition or doesn't. The Exhaustion condition is an exception to that rule."},
  {"id": "glossary_cone", "name": "Cone", "tag": "Area of Effect", "text": "A Cone is an area of effect that extends in straight lines from a point of origin in a direction its creator chooses. A Cone's width at any point along its length is equal to that point's distance from the point of origin. For example, a Cone is 15 feet wide at a point along its length that is 15 feet from the point of origin. The effect that creates a Cone specifies its maximum length.\n\nA Cone's point of origin isn't included in the area of effect unless its creator decides otherwise."},
  {"id": "glossary_cover", "name": "Cover", "tag": "", "text": "Cover provides a degree of protection to a target behind it. There are three degrees of cover, each of which provides a different benefit to a target: Half Cover (+2 bonus to AC and Dexterity saving throws), Three-Quarters Cover (+5 bonus to AC and Dexterity saving throws), and Total Cover (can't be targeted directly). If behind more than one degree of cover, a target benefits only from the most protective degree. See also \"Playing the Game\" (\"Combat\")."},
  {"id": "glossary_crawling", "name": "Crawling", "tag": "", "text": "While you're crawling, each foot of movement costs 1 extra foot (2 extra feet in Difficult Terrain). See also \"Speed.\""},
  {"id": "glossary_creature", "name": "Creature", "tag": "", "text": "Any being in the game, including a player's character, is a creature. See also \"Creature Type.\""},
  {"id": "glossary_creature_type", "name": "Creature Type", "tag": "", "text": "Every creature, including every player character, has a tag in the rules that identifies the type of creature it is. Most player characters are of the Humanoid type. These are the game's creature types:\n\nAberration Beast Celestial Construct Dragon"},
  {"id": "glossary_elemental_fey_fiend_giant_humanoid", "name": "Elemental Fey Fiend Giant Humanoid", "tag": "", "text": "Monstrosity Ooze Plant Undead\n\nThe types don't have rules themselves, but some rules in the game affect creatures of certain types in different ways."},
  {"id": "glossary_critical_hit", "name": "Critical Hit", "tag": "", "text": "If you roll a 20 on the d20 for an attack roll, you score a Critical Hit, and the attack hits regardless of any modifiers or the target's AC. A Critical Hit lets you roll extra dice for the attack's damage against the target. Roll all of the attack's damage dice twice and add them together. Then add any relevant modifiers. See also \"Playing the Game\" (\"Damage and Healing\")."},
  {"id": "glossary_cube", "name": "Cube", "tag": "Area of Effect", "text": "A Cube is an area of effect that extends in straight lines from a point of origin located anywhere on a face of the Cube. The effect that creates a Cube specifies its size, which is the length of each side.\n\nA Cube's point of origin isn't included in the area of effect unless its creator decides otherwise."},
  {"id": "glossary_curses", "name": "Curses", "tag": "", "text": "Some game effects curse a creature or an object. The effect that confers a curse defines what the curse does. Curses can be removed by the Remove Curse and Greater Restoration spells or other magic that explicitly ends curses."},
  {"id": "glossary_cylinder", "name": "Cylinder", "tag": "Area of Effect", "text": "A Cylinder is an area of effect that extends in straight lines from a point of origin located at the center of the circular top or bottom of the Cylinder. The effect that creates a Cylinder specifies the radius of the Cylinder's base and the Cylinder's height.\n\nA Cylinder's point of origin is included in the area of effect.\n\nD20 Test\n\nD20 Tests encompass the three main d20 rolls of the game: ability checks, attack rolls, and saving throws. If something in the game affects D20 Tests, it affects all three of these rolls. The GM determines whether a D20 Test is warranted in a given circumstance. See also \"Playing the Game\" (\"D20 Tests\")."},
  {"id": "glossary_damage", "name": "Damage", "tag": "", "text": "Damage represents harm that causes a creature or an object to lose Hit Points."},
  {"id": "glossary_damage_roll", "name": "Damage Roll", "tag": "", "text": "A damage roll is a die roll, adjusted by any applicable modifiers, that deals damage to a target. See also \"Playing the Game\" (\"Damage and Healing\")."},
  {"id": "glossary_damage_threshold", "name": "Damage Threshold", "tag": "", "text": "A creature or an object that has a damage threshold has Immunity to all damage unless it takes an amount of damage from a single attack or effect equal to or greater than its damage threshold, in which case it takes that entire instance of damage. Any damage that fails to meet or exceed the damage threshold is superficial and doesn't reduce Hit Points. For example, if an object has a damage threshold of 10, the object takes no damage if 9 damage is dealt to it, since that damage fails to exceed the threshold. If the same object is dealt 11 damage, it takes all of that damage."},
  {"id": "glossary_damage_types", "name": "Damage Types", "tag": "", "text": "Attacks and other harmful effects deal different types of damage. Damage types have no rules of their own, but other rules, such as Resistance, rely on the types. The Damage Types table offers examples to help a GM assign a type to a new effect.\n\nDamage Types\n\nType\n\nExamples\n\nAcid"},
  {"id": "glossary_corrosive_liquids_digestive_enzymes", "name": "Corrosive liquids, digestive enzymes", "tag": "", "text": "Bludgeoning Blunt objects, constriction, falling\n\nCold\n\nFreezing water, icy blasts\n\nFire\n\nFlames, unbearable heat\n\nForce\n\nPure magical energy\n\nLightning\n\nElectricity\n\nType Necrotic Piercing Poison Psychic Radiant Slashing Thunder\n\nExamples Life-draining energy Fangs, puncturing objects Toxic gas, venom Mind-rending energy Holy energy, searing radiation Claws, cutting objects Concussive sound"},
  {"id": "glossary_darkness", "name": "Darkness", "tag": "", "text": "An area of Darkness is Heavily Obscured. See also \"Heavily Obscured\" and \"Playing the Game\" (\"Exploration\")."},
  {"id": "glossary_darkvision", "name": "Darkvision", "tag": "", "text": "If you have Darkvision, you can see in Dim Light within a specified range as if it were Bright Light and in Darkness within that range as if it were Dim Light. You discern colors in that Darkness only as shades of gray. See also \"Playing the Game\" (\"Exploration\")."},
  {"id": "glossary_dash", "name": "Dash", "tag": "Action", "text": "When you take the Dash action, you gain extra movement for the current turn. The increase equals your Speed after applying any modifiers. With a Speed of 30 feet, for example, you can move up to 60 feet on your turn if you Dash. If your Speed of 30 feet is reduced to 15 feet, you can move up to 30 feet this turn if you Dash.\n\nIf you have a special speed, such as a Fly Speed or Swim Speed, you can use that speed instead of your Speed when you take this action. You choose which speed to use each time you take it. See also \"Speed.\""},
  {"id": "glossary_dead", "name": "Dead", "tag": "", "text": "A dead creature has no Hit Points and can't regain them unless it is first revived by magic such as the Raise Dead or Revivify spell. When such a spell is cast, the spirit knows who is casting it and can refuse. The spirit of a dead creature has left the body and departed for the Outer Planes, and reviving the creature requires calling the spirit back.\n\nIf the creature returns to life, the revival effect determines the creature's current Hit Points. Unless otherwise stated, the creature returns to life with any conditions, magical contagions, or curses that were affecting it at death if the durations of those effects are still ongoing. If the creature died with any Exhaustion levels, it returns with 1 fewer level. If the creature had Attunement to one or more magic items, it is no longer attuned to them."},
  {"id": "glossary_deafened", "name": "Deafened", "tag": "Condition", "text": "While you have the Deafened condition, you experience the following effect.\n\nCan't Hear. You can't hear and automatically fail any ability check that requires hearing."},
  {"id": "glossary_death_saving_throw", "name": "Death Saving Throw", "tag": "", "text": "A player character must make a Death Saving Throw (also called a Death Save) if they start their turn with 0 Hit Points. See also \"Playing the Game\" (\"Damage and Healing\")."},
  {"id": "glossary_dehydration", "name": "Dehydration", "tag": "Hazard", "text": "A creature requires an amount of water per day based on its size, as shown in the Water Needs per Day table. A creature that drinks less than half the required water for a day gains 1 Exhaustion level at the day's end. Exhaustion caused by dehydration can't be removed until the creature drinks the full amount of water required for a day. See also \"Exhaustion.\"\n\nWater Needs per Day\n\nSize\n\nWater\n\nTiny\n\n1/4 gallon\n\nSmall\n\n1 gallon\n\nMedium 1 gallon\n\nSize\n\nWater\n\nLarge\n\n4 gallons\n\nHuge\n\n16 gallons\n\nGargantuan 64 gallons"},
  {"id": "glossary_difficult_terrain", "name": "Difficult Terrain", "tag": "", "text": "If a space is Difficult Terrain, every foot of movement in that space costs 1 extra foot. For example, moving 5 feet through Difficult Terrain costs 10 feet of movement. Difficult Terrain isn't cumulative; either a space is Difficult Terrain or it isn't.\n\nA space is Difficult Terrain if the space contains any of the following or something similar:\n\n• A creature that isn't Tiny or your ally • Furniture that is sized for creatures of your size or\n\nlarger • Heavy snow, ice, rubble, or undergrowth • Liquid that's between shinand waist-deep • A narrow opening sized for a creature one size\n\nsmaller than you • A slope of 20 degrees or more"},
  {"id": "glossary_difficulty_class", "name": "Difficulty Class", "tag": "", "text": "A Difficulty Class (DC) is the target number for an ability check or a saving throw. See also \"Playing the Game\" (\"D20 Tests\")."},
  {"id": "glossary_dim_light", "name": "Dim Light", "tag": "", "text": "An area with Dim Light is Lightly Obscured. See also \"Lightly Obscured\" and \"Playing the Game\" (\"Exploration\")."},
  {"id": "glossary_disadvantage", "name": "Disadvantage", "tag": "", "text": "If you have Disadvantage on a D20 Test, roll two d20s and use the lower roll. A roll can't be affected by more than one Disadvantage, and Advantage and Disadvantage on the same roll cancel each other. See also \"Playing the Game\" (\"D20 Tests\")."},
  {"id": "glossary_disengage", "name": "Disengage", "tag": "Action", "text": "If you take the Disengage action, your movement doesn't provoke Opportunity Attacks for the rest of the current turn."},
  {"id": "glossary_dodge", "name": "Dodge", "tag": "Action", "text": "If you take the Dodge action, you gain the following benefits: until the start of your next turn, any attack roll made against you has Disadvantage if you can see the attacker, and you make Dexterity saving throws with Advantage.\n\nYou lose these benefits if you have the Incapacitated condition or if your Speed is 0."},
  {"id": "glossary_emanation", "name": "Emanation", "tag": "Area of Effect", "text": "An Emanation is an area of effect that extends in straight lines from a creature or an object in all directions. The effect that creates an Emanation specifies the distance it extends.\n\nAn Emanation moves with the creature or object that is its origin unless it is an instantaneous or a stationary effect.\n\nAn Emanation's origin (creature or object) isn't included in the area of effect unless its creator decides otherwise."},
  {"id": "glossary_encounter", "name": "Encounter", "tag": "", "text": "An encounter is a scene in an adventure that is part of at least one of the game's three pillars: social interaction, exploration, or combat. See also \"Playing the Game\" (\"Social Interaction,\" \"Exploration,\" and \"Combat\")."},
  {"id": "glossary_enemy", "name": "Enemy", "tag": "", "text": "A creature is your enemy if it fights against you in combat, actively works to harm you, or is designated as your enemy by the rules or GM."},
  {"id": "glossary_exhaustion", "name": "Exhaustion", "tag": "Condition", "text": "While you have the Exhaustion condition, you experience the following effects.\n\nExhaustion Levels. This condition is cumulative. Each time you receive it, you gain 1 Exhaustion level. You die if your Exhaustion level is 6.\n\nD20 Tests Affected. When you make a D20 Test, the roll is reduced by 2 times your Exhaustion level.\n\nSpeed Reduced. Your Speed is reduced by a number of feet equal to 5 times your Exhaustion level.\n\nRemoving Exhaustion Levels. Finishing a Long Rest removes 1 of your Exhaustion levels. When your Exhaustion level reaches 0, the condition ends."},
  {"id": "glossary_experience_points", "name": "Experience Points", "tag": "", "text": "As they overcome challenges and complete adventures, characters earn Experience Points (XP), which are awarded by the Game Master. When a character's XP total crosses certain thresholds, the character's level increases. See also \"Level Advancement.\""},
  {"id": "glossary_expertise", "name": "Expertise", "tag": "", "text": "Expertise is a feature that enhances your use of a skill proficiency. When you make an ability check with a skill proficiency in which you have Expertise, your Proficiency Bonus is doubled for that check unless the bonus is doubled by another feature.\n\nIf you gain Expertise, you gain it in one skill in which you have proficiency. You can't have Expertise in the same skill proficiency more than once.\n\nSee also \"Playing the Game\" (\"Proficiency\")."},
  {"id": "glossary_falling", "name": "Falling", "tag": "Hazard", "text": "A creature that falls takes 1d6 Bludgeoning damage at the end of the fall for every 10 feet it fell, to a maximum of 20d6. When the creature lands, it has the Prone condition unless it avoids taking any damage from the fall.\n\nA creature that falls into water or another liquid can use its Reaction to make a DC 15 Strength (Athletics) or Dexterity (Acrobatics) check to hit the surface head or feet first. On a successful check, any damage resulting from the fall is halved."},
  {"id": "glossary_flying", "name": "Flying", "tag": "", "text": "A variety of effects allow a creature to fly. While flying, you fall if you have the Incapacitated or Prone condition or your Fly Speed is reduced to 0. You can stay aloft in those circumstances if you can hover. See also \"Falling\" and \"Fly Speed.\""},
  {"id": "glossary_fly_speed", "name": "Fly Speed", "tag": "", "text": "A Fly Speed can be used to travel through the air. While you have a Fly Speed, you can stay aloft until you land, fall, or die. See also \"Flying\" and \"Speed.\""},
  {"id": "glossary_friendly", "name": "Friendly", "tag": "Attitude", "text": "A Friendly creature views you favorably. You have Advantage on an ability check to influence a Friendly creature. See also \"Influence.\""},
  {"id": "glossary_frightened", "name": "Frightened", "tag": "Condition", "text": "While you have the Frightened condition, you experience the following effects.\n\nAbility Checks and Attacks Affected. You have Disadvantage on ability checks and attack rolls while the source of fear is within line of sight.\n\nCan't Approach. You can't willingly move closer to the source of fear."},
  {"id": "glossary_grappled", "name": "Grappled", "tag": "Condition", "text": "While you have the Grappled condition, you experience the following effects.\n\nSpeed 0. Your Speed is 0 and can't increase. Attacks Affected. You have Disadvantage on attack rolls against any target other than the grappler. Movable. The grappler can drag or carry you when it moves, but every foot of movement costs it 1 extra foot unless you are Tiny or two or more sizes smaller than it."},
  {"id": "glossary_grappling", "name": "Grappling", "tag": "", "text": "A creature can grapple another creature. Characters typically grapple by using an Unarmed Strike. Many monsters have special attacks that allow them to quickly grapple prey. However a grapple is initiated, it follows these rules. See also \"Unarmed Strike\" and \"Grappled.\"\n\nGrappled Condition. Successfully grappling a creature gives it the Grappled condition.\n\nOne Grapple per Hand. A creature must have a hand free to grapple another creature. Some stat blocks and game effects allow a creature to grapple using a tentacle, a maw, or another body part. Whatever part a grappler uses, it can grapple only one creature at a time with that part, and the grappler can't use that part to target another creature unless it ends the grapple.\n\nEnding a Grapple. A Grappled creature can use its action to make a Strength (Athletics) or Dexterity (Acrobatics) check against the grapple's escape DC, ending the condition on itself on a success. The condition also ends if the grappler has the Incapacitated condition or if the distance between the Grappled target and the grappler exceeds the grapple's range. In addition, the grappler can release the target at any time (no action required)."},
  {"id": "glossary_hazard", "name": "Hazard", "tag": "", "text": "A hazard is an environmental danger. See also \"Burning,\" \"Dehydration,\" \"Falling,\" \"Malnutrition,\" and \"Suffocation.\""},
  {"id": "glossary_healing", "name": "Healing", "tag": "", "text": "Healing is how you regain Hit Points. See also \"Playing the Game\" (\"Damage and Healing\")."},
  {"id": "glossary_heavily_obscured", "name": "Heavily Obscured", "tag": "", "text": "You have the Blinded condition while trying to see something in a Heavily Obscured space. See also \"Blinded,\" \"Darkness,\" and \"Playing the Game\" (\"Exploration\")."},
  {"id": "glossary_help", "name": "Help", "tag": "Action", "text": "When you take the Help action, you do one of the following.\n\nAssist an Ability Check. Choose one of your skill or tool proficiencies and one ally who is near\n\nenough for you to assist verbally or physically when they make an ability check. That ally has Advantage on the next ability check they make with the chosen skill or tool. This benefit expires if the ally doesn't use it before the start of your next turn. The GM has final say on whether your assistance is possible.\n\nAssist an Attack Roll. You momentarily distract an enemy within 5 feet of you, giving Advantage to the next attack roll by one of your allies against that enemy. This benefit expires at the start of your next turn."},
  {"id": "glossary_heroic_inspiration", "name": "Heroic Inspiration", "tag": "", "text": "If you (a player character) have Heroic Inspiration, you can expend it to reroll any die immediately after rolling it, and you must use the new roll.\n\nIf you gain Heroic Inspiration but already have it, it's lost unless you give it to a player character who lacks it."},
  {"id": "glossary_hide", "name": "Hide", "tag": "Action", "text": "With the Hide action, you try to hide yourself. To do so, you must succeed on a DC 15 Dexterity (Stealth) check while you're Heavily Obscured or behind Three-Quarters Cover or Total Cover, and you must be out of any enemy's line of sight; if you can see a creature, you can discern whether it can see you.\n\nOn a successful check, you have the Invisible condition while hidden. Make note of your check's total, which is the DC for a creature to find you with a Wisdom (Perception) check.\n\nYou stop being hidden immediately after any of the following occurs: you make a sound louder than a whisper, an enemy finds you, you make an attack roll, or you cast a spell with a Verbal component."},
  {"id": "glossary_high_jump", "name": "High Jump", "tag": "", "text": "When you make a High Jump, you leap into the air a number of feet equal to 3 plus your Strength modifier (minimum of 0 feet) if you move at least 10 feet on foot immediately before the jump. When you make a standing High Jump, you can jump only half that distance. Either way, each foot of the jump costs a foot of movement.\n\nYou can extend your arms half your height above yourself during the jump. Thus, you can reach a distance equal to the height of the jump plus 1½ times your height."},
  {"id": "glossary_hit_point_dice", "name": "Hit Point Dice", "tag": "", "text": "Hit Point Dice, or Hit Dice for short, help determine a player character's Hit Point maximum, as explained in \"Character Creation.\" Most monsters also have Hit Dice. A creature can spend Hit Dice during a Short Rest to regain Hit Points. See also \"Short Rest.\""},
  {"id": "glossary_hit_points", "name": "Hit Points", "tag": "", "text": "Hit Points (HP) are a measure of how difficult it is to kill or destroy a creature or an object. Damage reduces Hit Points, and healing restores them. You can't have more Hit Points than your Hit Point maximum, and you can't have less than 0. See also \"Breaking Objects\" and \"Playing the Game\" (\"Damage and Healing\")."},
  {"id": "glossary_hostile", "name": "Hostile", "tag": "Attitude", "text": "A Hostile creature views you unfavorably. You have Disadvantage on an ability check to influence a Hostile creature. See also \"Influence.\""},
  {"id": "glossary_hover", "name": "Hover", "tag": "", "text": "Some creatures can hover, as noted in their stat blocks, and some spells and other effects grant the ability to hover. Hovering while flying prevents you from falling in certain circumstances. See also \"Flying.\""},
  {"id": "glossary_illusions", "name": "Illusions", "tag": "", "text": "Spells and other effects sometimes create magical illusions. Such an effect defines what the illusion does and which senses or mental faculties it deceives.\n\nIf an illusion manifests in space, the illusion is insubstantial and weightless, yet it seems to be affected by the environment as if the illusion were real unless the effect that created it specifies otherwise. For example, a visual illusion of a creature casts shadows and reflections, and wind appears to affect the illusory creature. Similarly, an audible illusion echoes in an echoey space."},
  {"id": "glossary_immunity", "name": "Immunity", "tag": "", "text": "If you have Immunity to a damage type or a condition, it doesn't affect you in any way."},
  {"id": "glossary_improvised_weapons", "name": "Improvised Weapons", "tag": "", "text": "An improvised weapon is an object wielded as a makeshift weapon, such as broken glass, a table leg, or a frying pan. A Simple or Martial weapon also counts as an improvised weapon if it's wielded in a way contrary to its design; if you use a Ranged weapon to make a melee attack or throw a Melee weapon that lacks the Thrown property, the weapon counts as an improvised weapon. An improvised weapon follows the rules below.\n\nProficiency. Don't add your Proficiency Bonus to attack rolls with an improvised weapon.\n\nDamage. On a hit, the weapon deals 1d4 damage of a type the GM thinks is appropriate for the object.\n\nRange. If you throw the weapon, it has a normal range of 20 feet and a long range of 60 feet.\n\nWeapon Equivalents. If an improvised weapon resembles a Simple or Martial weapon, the GM may say it functions as that weapon and uses that weapon's rules. For example, the GM could treat a table leg as a Club."},
  {"id": "glossary_incapacitated", "name": "Incapacitated", "tag": "Condition", "text": "While you have the Incapacitated condition, you experience the following effects.\n\nInactive. You can't take any action, Bonus Action, or Reaction.\n\nNo Concentration. Your Concentration is broken. Speechless. You can't speak. Surprised. If you're Incapacitated when you roll Initiative, you have Disadvantage on the roll."},
  {"id": "glossary_indifferent", "name": "Indifferent", "tag": "Attitude", "text": "An Indifferent creature has no desire to help or hinder you. Indifferent is the default attitude of a monster. See also \"Influence.\""},
  {"id": "glossary_influence", "name": "Influence", "tag": "Action", "text": "With the Influence action, you urge a monster to do something. Describe or roleplay how you're communicating with the monster. Are you trying to deceive, intimidate, amuse, or gently persuade? The GM then determines whether the monster feels willing, unwilling, or hesitant due to your interaction; this determination establishes whether an ability check is necessary, as explained below.\n\nWilling. If your urging aligns with the monster's desires, no ability check is necessary; the monster fulfills your request in a way it prefers.\n\nUnwilling. If your urging is repugnant to the monster or counter to its alignment, no ability check is necessary; it doesn't comply.\n\nHesitant. If you urge the monster to do something that it is hesitant to do, you must make an ability check, which is affected by the monster's attitude: Indifferent, Friendly, or Hostile, each of which is defined in this glossary. The Influence Checks table suggests which ability check to make based on how you're interacting with the monster. The GM chooses the check, which has a default DC equal to 15 or the monster's Intelligence score, whichever is higher. On a successful check, the monster does as urged. On a failed check, you must wait 24 hours (or a duration set by the GM) before urging it in the same way again.\n\nInfluence Checks\n\nAbility Check Charisma (Deception)\n\nCharisma (Intimidation) Charisma (Performance) Charisma (Persuasion)\n\nWisdom (Animal Handling)\n\nInteraction Deceiving a monster that understands you Intimidating a monster Amusing a monster Persuading a monster that understands you Gently coaxing a Beast or Monstrosity"},
  {"id": "glossary_initiative", "name": "Initiative", "tag": "", "text": "Initiative determines the order of turns during combat. The combat rules in \"Playing the Game\" explain how to roll Initiative.\n\nSometimes a GM might have combatants use their Initiative scores instead of rolling Initiative. Your Initiative score equals 10 plus your Dexterity modifier. If you have Advantage on Initiative rolls, increase your Initiative score by 5. If you have Disadvantage on those rolls, decrease that score by 5. See also \"Playing the Game\" (\"Combat\")."},
  {"id": "glossary_invisible", "name": "Invisible", "tag": "Condition", "text": "While you have the Invisible condition, you experience the following effects.\n\nSurprise. If you're Invisible when you roll Initiative, you have Advantage on the roll.\n\nConcealed. You aren't affected by any effect that requires its target to be seen unless the effect's creator can somehow see you. Any equipment you are wearing or carrying is also concealed.\n\nAttacks Affected. Attack rolls against you have Disadvantage, and your attack rolls have Advantage. If a creature can somehow see you, you don't gain this benefit against that creature."},
  {"id": "glossary_jumping", "name": "Jumping", "tag": "", "text": "When you jump, you make either a Long Jump (horizontal) or a High Jump (vertical). See also \"Long Jump\" and \"High Jump.\""},
  {"id": "glossary_knocking_out_a_creature", "name": "Knocking Out a Creature", "tag": "", "text": "When you would reduce a creature to 0 Hit Points with a melee attack, you can instead reduce the creature to 1 Hit Point. The creature then has the Unconscious condition and starts a Short Rest.\n\nThe creature remains Unconscious until it regains any Hit Points or until someone uses an action to administer first aid to it, which requires a successful DC 10 Wisdom (Medicine) check."},
  {"id": "glossary_lightly_obscured", "name": "Lightly Obscured", "tag": "", "text": "You have Disadvantage on Wisdom (Perception) checks to see something in a Lightly Obscured space. See also \"Dim Light\" and \"Playing the Game\" (\"Exploration\")."},
  {"id": "glossary_line", "name": "Line", "tag": "Area of Effect", "text": "A Line is an area of effect that extends from a point of origin in a straight path along its length and covers an area defined by its width. The effect that creates a Line specifies its length and width.\n\nA Line's point of origin isn't included in the area of effect unless its creator decides otherwise."},
  {"id": "glossary_long_jump", "name": "Long Jump", "tag": "", "text": "When you make a Long Jump, you leap horizontally a number of feet up to your Strength score if you\n\nmove at least 10 feet immediately before the jump. When you make a standing Long Jump, you can leap only half that distance. Either way, each foot you jump costs a foot of movement.\n\nIf you land in Difficult Terrain, you must succeed on a DC 10 Dexterity (Acrobatics) check or have the Prone condition.\n\nThis Long Jump rule assumes that the height of the jump doesn't matter, such as a jump across a stream or chasm. At your GM's option, you must succeed on a DC 10 Strength (Athletics) check to clear a low obstacle (no taller than a quarter of the jump's distance), such as a hedge or low wall. Otherwise, you hit the obstacle."},
  {"id": "glossary_long_rest", "name": "Long Rest", "tag": "", "text": "A Long Rest is a period of extended downtime--at least 8 hours--available to any creature. During a Long Rest, you sleep for at least 6 hours and perform no more than 2 hours of light activity, such as reading, talking, eating, or standing watch.\n\nDuring sleep, you have the Unconscious condition. After you finish a Long Rest, you must wait at least 16 hours before starting another one.\n\nBenefits of the Rest. To start a Long Rest, you must have at least 1 Hit Point. When you finish the rest, you gain the following benefits:\n\nRegain All HP. You regain all lost Hit Points and all spent Hit Point Dice. If your Hit Point maximum was reduced, it returns to normal.\n\nAbility Scores Restored. If any of your ability scores were reduced, they return to normal.\n\nExhaustion Reduced. If you have the Exhaustion condition, its level decreases by 1.\n\nSpecial Feature. Some features are recharged by a Long Rest. If you have such a feature, it recharges in the way specified in its description.\n\nInterrupting the Rest. A Long Rest is stopped by the following interruptions:\n\n• Rolling Initiative • Casting a spell other than a cantrip • Taking any damage – 1 hour of walking or other physical exertion\n\nIf you rested at least 1 hour before the interruption, you gain the benefits of a Short Rest. See also \"Short Rest.\"\n\nYou can resume a Long Rest immediately after an interruption. If you do so, the rest requires 1 additional hour per interruption to finish."},
  {"id": "glossary_magic", "name": "Magic", "tag": "Action", "text": "When you take the Magic action, you cast a spell that has a casting time of an action or use a feature or magic item that requires a Magic action to be activated.\n\nIf you cast a spell that has a casting time of 1 minute or longer, you must take the Magic action on each turn of that casting, and you must maintain Concentration while you do so. If your Concentration is broken, the spell fails, but you don't expend a spell slot. See also \"Concentration.\""},
  {"id": "glossary_magical_effect", "name": "Magical Effect", "tag": "", "text": "An effect is magical if it is created by a spell, a magic item, or a phenomenon that a rule labels as magical."},
  {"id": "glossary_malnutrition", "name": "Malnutrition", "tag": "Hazard", "text": "A creature needs an amount of food per day based on its size, as shown in the Food Needs per Day table. A creature that eats but consumes less than half the required food for a day must succeed on a DC 10 Constitution saving throw or gain 1 Exhaustion level at the day's end. A creature that eats nothing for 5 days automatically gains 1 Exhaustion level at the end of the fifth day as well as an additional level at the end of each subsequent day without food.\n\nExhaustion caused by malnutrition can't be removed until the creature eats the full amount of food required for a day. See also \"Exhaustion.\"\n\nFood Needs per Day\n\nSize\n\nFood\n\nTiny\n\n1/4 pound\n\nSmall\n\n1 pound\n\nMedium 1 pound\n\nSize\n\nFood\n\nLarge\n\n4 pounds\n\nHuge\n\n16 pounds\n\nGargantuan 64 pounds"},
  {"id": "glossary_monster", "name": "Monster", "tag": "", "text": "A monster is a creature controlled by the GM, even if the creature is benevolent. See also \"Creature\" and \"NPC.\""},
  {"id": "glossary_nonplayer_character", "name": "Nonplayer Character", "tag": "", "text": "A nonplayer character (NPC) is a monster that has a personal name and a distinct personality. See also \"Monster.\""},
  {"id": "glossary_object", "name": "Object", "tag": "", "text": "An object is a nonliving, distinct thing. Composite things, like buildings, comprise more than one object. See also \"Breaking Objects.\""},
  {"id": "glossary_occupied_space", "name": "Occupied Space", "tag": "", "text": "A space is occupied if a creature is in it or if it is completely filled by objects."},
  {"id": "glossary_opportunity_attacks", "name": "Opportunity Attacks", "tag": "", "text": "You can make an Opportunity Attack when a creature that you can see leaves your reach using its action, its Bonus Action, its Reaction, or one of its speeds. To make the Opportunity Attack, take a Reaction to make one melee attack with a weapon or an Unarmed Strike against the provoking creature. The attack occurs right before the creature leaves your reach. See also \"Playing the Game\" (\"Combat\")."},
  {"id": "glossary_paralyzed", "name": "Paralyzed", "tag": "Condition", "text": "While you have the Paralyzed condition, you experience the following effects.\n\nIncapacitated. You have the Incapacitated condition.\n\nSpeed 0. Your Speed is 0 and can't increase. Saving Throws Affected. You automatically fail Strength and Dexterity saving throws. Attacks Affected. Attack rolls against you have Advantage. Automatic Critical Hits. Any attack roll that hits you is a Critical Hit if the attacker is within 5 feet of you."},
  {"id": "glossary_passive_perception", "name": "Passive Perception", "tag": "", "text": "Passive Perception is a score that reflects a creature's general awareness of its surroundings. The GM uses this score when determining whether a creature notices something without consciously making a Wisdom (Perception) check.\n\nA creature's Passive Perception equals 10 plus the creature's Wisdom (Perception) check bonus. If the creature has Advantage on such checks, increase the score by 5. If the creature has Disadvantage on them, decrease the score by 5. For example, a level 1 character with a Wisdom of 15 and proficiency in Perception has a Passive Perception of 14 (10 + 2 + 2). If that character has Advantage on Wisdom (Perception) checks, the score becomes 19."},
  {"id": "glossary_per_day", "name": "Per Day", "tag": "", "text": "If a rule says you can use something a certain number of times per day, that means you must finish a Long Rest to use it again after you run out of uses."},
  {"id": "glossary_petrified", "name": "Petrified", "tag": "Condition", "text": "While you have the Petrified condition, you experience the following effects.\n\nTurned to Inanimate Substance. You are transformed, along with any nonmagical objects you are wearing and carrying, into a solid inanimate substance (usually stone). Your weight increases by a factor of ten, and you cease aging.\n\nIncapacitated. You have the Incapacitated condition.\n\nSpeed 0. Your Speed is 0 and can't increase. Attacks Affected. Attack rolls against you have Advantage. Saving Throws Affected. You automatically fail Strength and Dexterity saving throws. Resist Damage. You have Resistance to all damage. Poison Immunity. You have Immunity to the Poisoned condition."},
  {"id": "glossary_player_character", "name": "Player Character", "tag": "", "text": "A player character is a character controlled by a player. See also \"Character Creation.\""},
  {"id": "glossary_poisoned", "name": "Poisoned", "tag": "Condition", "text": "While you have the Poisoned condition, you experience the following effect.\n\nAbility Checks and Attacks Affected. You have Disadvantage on attack rolls and ability checks."},
  {"id": "glossary_possession", "name": "Possession", "tag": "", "text": "Some effects cause a creature to be possessed by another creature or entity. A possessing effect defines how the possession operates. Possession can be prevented by the Protection from Evil and Good spell and ended by the Dispel Evil and Good spell."},
  {"id": "glossary_proficiency", "name": "Proficiency", "tag": "", "text": "If you have proficiency with something, you can add your Proficiency Bonus to any D20 Test you make using that thing. A creature might have proficiency in a skill or saving throw or with a weapon or tool. See also \"Playing the Game\" (\"Proficiency\")."},
  {"id": "glossary_prone", "name": "Prone", "tag": "Condition", "text": "While you have the Prone condition, you experience the following effects.\n\nRestricted Movement. Your only movement options are to crawl or to spend an amount of movement equal to half your Speed (round down) to right yourself and thereby end the condition. If your Speed is 0, you can't right yourself.\n\nAttacks Affected. You have Disadvantage on attack rolls. An attack roll against you has Advantage if the attacker is within 5 feet of you. Otherwise, that attack roll has Disadvantage."},
  {"id": "glossary_reach", "name": "Reach", "tag": "", "text": "A creature has a reach of 5 feet unless a rule says otherwise."},
  {"id": "glossary_reaction", "name": "Reaction", "tag": "", "text": "A Reaction is a special action taken in response to a trigger defined in the Reaction's description. You can take a Reaction on another creature's turn, and if you take it on your turn, you can do so even if you also take an action, a Bonus Action, or both. Once you take a Reaction, you can't take another one until the start of your next turn. The Opportunity Attack is a Reaction available to all creatures. See also \"Opportunity Attacks\" and \"Playing the Game\" (\"Actions\")."},
  {"id": "glossary_ready", "name": "Ready", "tag": "Action", "text": "You take the Ready action to wait for a particular circumstance before you act. To do so, you take this action on your turn, which lets you act by taking a Reaction before the start of your next turn.\n\nFirst, you decide what perceivable circumstance will trigger your Reaction. Then, you choose the action you will take in response to that trigger, or you choose to move up to your Speed in response to it. Examples include \"If the cultist steps on the\n\ntrapdoor, I'll pull the lever that opens it,\" and \"If the zombie steps next to me, I move away.\"\n\nWhen the trigger occurs, you can either take your Reaction right after the trigger finishes or ignore the trigger.\n\nWhen you Ready a spell, you cast it as normal (expending any resources used to cast it) but hold its energy, which you release with your Reaction when the trigger occurs. To be readied, a spell must have a casting time of an action, and holding on to the spell's magic requires Concentration, which you can maintain up to the start of your next turn. If your Concentration is broken, the spell dissipates without taking effect."},
  {"id": "glossary_resistance", "name": "Resistance", "tag": "", "text": "If you have Resistance to a damage type, damage of that type is halved against you (round down). Resistance is applied only once to an instance of damage. See also \"Playing the Game\" (\"Damage and Healing\")."},
  {"id": "glossary_restrained", "name": "Restrained", "tag": "Condition", "text": "While you have the Restrained condition, you experience the following effects.\n\nSpeed 0. Your Speed is 0 and can't increase. Attacks Affected. Attack rolls against you have Advantage, and your attack rolls have Disadvantage. Saving Throws Affected. You have Disadvantage on Dexterity saving throws."},
  {"id": "glossary_ritual", "name": "Ritual", "tag": "", "text": "If you have a spell prepared that has the Ritual tag, you can cast that spell as a Ritual. The Ritual version of a spell takes 10 minutes longer to cast than normal. It also doesn't expend a spell slot, which means the ritual version of a spell can't be cast at a higher level. See also \"Spells.\""},
  {"id": "glossary_round_down", "name": "Round Down", "tag": "", "text": "Whenever you divide or multiply a number in the game, round down if you end up with a fraction, even if the fraction is one-half or greater. Some rules make an exception and tell you to round up."},
  {"id": "glossary_save", "name": "Save", "tag": "", "text": "Save is another name for a saving throw. See also \"Saving Throw.\""},
  {"id": "glossary_saving_throw", "name": "Saving Throw", "tag": "", "text": "A saving throw--also called a save--represents an attempt to avoid or resist a threat. You normally make a saving throw only when a rule requires you to do so, but you can decide to fail the save without rolling. The result of a save is detailed in the effect that allowed it. If a target is forced to make a save and lacks the ability score used by it, the target automatically fails. See also \"Playing the Game\" (\"D20 Tests\")."},
  {"id": "glossary_search", "name": "Search", "tag": "Action", "text": "When you take the Search action, you make a Wisdom check to discern something that isn't obvious. The Search table suggests which skills are applicable when you take this action, depending on what you're trying to detect.\n\nSearch\n\nSkill Insight Medicine Perception Survival\n\nThing to Detect Creature's state of mind Creature's ailment or cause of death Concealed creature or object Tracks or food"},
  {"id": "glossary_shape_shifting", "name": "Shape-Shifting", "tag": "", "text": "If an effect, such as Wild Shape or the Polymorph spell, lets you shape-shift, its description specifies what happens to you. Unless that description says otherwise, any ongoing effects on you--conditions, spells, curses, and the like--carry over from one form to the other. You revert to your true form if you die."},
  {"id": "glossary_short_rest", "name": "Short Rest", "tag": "", "text": "A Short Rest is a 1-hour period of downtime, during which a creature does nothing more strenuous than reading, talking, eating, or standing watch. To start a Short Rest, you must have at least 1 Hit Point.\n\nBenefits of the Rest. When you finish the rest, you gain the following benefits:\n\nSpend Hit Point Dice. You can spend one or more of your Hit Point Dice to regain Hit Points. For each Hit Point Die you spend in this way, roll the die and add your Constitution modifier to it. You regain Hit Points equal to the total (minimum of 1 Hit Point). You can decide to spend an additional Hit Point Die after each roll.\n\nSpecial Feature. Some features are recharged by a Short Rest. If you have such a feature, it recharges in the way specified in its description.\n\nInterrupting the Rest. A Short Rest is stopped by the following interruptions:\n\n• Rolling Initiative • Casting a spell other than a cantrip • Taking any damage\n\nAn interrupted Short Rest confers no benefits."},
  {"id": "glossary_simultaneous_effects", "name": "Simultaneous Effects", "tag": "", "text": "If two or more things happen at the same time on a turn, the person at the game table--player or GM-- whose turn it is decides the order in which those things happen. For example, if two effects occur at the start of a player character's turn, the player decides which of the effects happens first."},
  {"id": "glossary_size", "name": "Size", "tag": "", "text": "A creature or an object belongs to a size category: Tiny, Small, Medium, Large, Huge, or Gargantuan. A creature's size determines how much space the creature occupies in combat. An object's size affects its Hit Points. See also \"Breaking Objects\" and \"Playing the Game\" (\"Combat\")."},
  {"id": "glossary_skill", "name": "Skill", "tag": "", "text": "A skill is an area of specialization associated with an ability check. If you have proficiency in a skill, you can add your Proficiency Bonus when you make an ability check associated with that skill. See also \"Playing the Game\" (\"Proficiency\")."},
  {"id": "glossary_speed", "name": "Speed", "tag": "", "text": "A creature has a Speed, which is the distance in feet the creature can cover when it moves on its turn. See also \"Climbing,\" \"Crawling,\" \"Flying,\" \"Jumping,\" \"Swimming\" and \"Playing the Game\" (\"Combat\").\n\nSpecial Speeds. Some creatures have special speeds, such as a Burrow Speed, Climb Speed, Fly Speed, or Swim Speed, each of which is defined in this glossary. If you have more than one speed, choose which one to use when you move; you can switch between the speeds during your move. Whenever you switch, subtract the distance already moved from the new speed. The result determines how much farther you can move. If the result is 0 or less, you can't use the new speed during the current move. For example, if you have a Speed of 30 and a Fly Speed of 40, you could fly 10 feet, walk 10 feet, and leap into the air to fly 20 feet more.\n\nChanges to Your Speeds. If an effect increases or decreases your Speed for a time, any special speed you have increases or decreases by an equal amount for the same duration. For example, if your Speed is reduced to 0 and you have a Climb Speed, your Climb Speed is also reduced to 0. Similarly, if your Speed is halved and you have a Fly Speed, your Fly Speed is also halved."},
  {"id": "glossary_spell", "name": "Spell", "tag": "", "text": "A spell is a magical effect that has the characteristics described in \"Spells.\""},
  {"id": "glossary_spell_attack", "name": "Spell Attack", "tag": "", "text": "A spell attack is an attack roll made as part of a spell or another magical effect. See also \"Spells\" (\"Casting Spells\")."},
  {"id": "glossary_spellcasting_focus", "name": "Spellcasting Focus", "tag": "", "text": "A Spellcasting Focus is an object that certain creatures can use in place of a spell's Material components if those materials aren't consumed by the spell and don't have a cost specified. Some classes allow its members to use certain types of Spellcasting Focuses. See also \"Spells\" (\"Casting Spells\")."},
  {"id": "glossary_sphere", "name": "Sphere", "tag": "Area of Effect", "text": "A Sphere is an area of effect that extends in straight lines from a point of origin outward in all directions. The effect that creates a Sphere specifies the distance it extends as the radius of the Sphere.\n\nA Sphere's point of origin is included in the Sphere's area of effect."},
  {"id": "glossary_stable", "name": "Stable", "tag": "", "text": "A creature is Stable if it has 0 Hit Points but isn't required to make Death Saving Throws. See also \"Playing the Game\" (\"Damage and Healing\")."},
  {"id": "glossary_stat_block", "name": "Stat Block", "tag": "", "text": "A stat block contains the game statistics of a monster. Each stat block includes the following information presented after the monster's name.\n\nSize. A monster is Tiny, Small, Medium, Large, Huge, or Gargantuan. See also \"Size.\"\n\nCreature Type. This entry notes the family of beings a monster belongs to, along with any descriptive tags. See also \"Creature Type.\"\n\nAlignment. An alignment is suggested for the monster, with the GM determining its actual alignment. See also \"Alignment.\"\n\nAC, Initiative, and HP. These entries give the monster's Armor Class, Initiative, and Hit Points, which are detailed in \"Playing the Game.\" In parentheses after the Hit Points, the monster's Hit Point Dice are provided, along with the contribution of its Constitution, if any, to its Hit Points. Following the Initiative modifier is an Initiative score. Some creatures that are created by magic lack Hit Dice and Initiative information.\n\nSpeed. Here the monster's Speed is provided, along with any special speeds. See also \"Burrow Speed,\" \"Climb Speed,\" \"Fly Speed,\" and \"Swim Speed.\"\n\nAbility Scores. A table provides the monster's ability scores, modifiers, and saving throw modifiers, all of which are detailed in \"Playing the Game.\"\n\nSkills. This entry lists the monster's skill proficiencies, if any. See also \"Playing the Game\" (\"Proficiency\").\n\nResistances and Vulnerabilities. These entries list the monster's Resistances and Vulnerabilities, if any. See also \"Resistance\" and \"Vulnerability.\"\n\nImmunities. This section lists the monster's damage and condition Immunities, if any. See also \"Immunity.\"\n\nGear. If the monster has any equipment that can be given away or retrieved, it's listed in this entry.\n\nSenses. This entry lists the monster's special senses, such as Darkvision, and its Passive Perception. See also \"Passive Perception.\"\n\nLanguages. This entry lists any languages the monster knows.\n\nCR. Challenge Rating summarizes the threat a monster poses and is detailed in \"Monsters.\" The Experience Points characters receive for defeating a monster and its Proficiency Bonus follow. Some creatures that are created by magic have no CR. See also \"Challenge Rating\" and \"Experience Points.\"\n\nTraits. The monster's traits, if any, are features that are active at all times or in certain situations.\n\nActions. The monster can take these actions in addition to those detailed in this glossary. See also \"Playing the Game\" (\"Actions\").\n\nBonus Actions. If the monster has Bonus Action options, they are listed in this section.\n\nReactions. If the monster can take special Reactions, those are listed in this section.\n\nAttack Notation. The entry for a monster's attack starts by identifying whether the attack is a melee or a ranged attack and then provides the attack roll's bonus, its reach or range, and what happens on a hit. An attack is against one target unless its entry says otherwise.\n\nSaving Throw Effect Notation. If an effect forces a saving throw, the effect's entry starts by identifying the kind of saving throw required and then provides the save's DC, a description of which creatures must make the save, and what happens on a failed or a successful save.\n\nDamage Notation. A stat block usually provides both a static number and a die expression for each instance of damage. For example, an attack might deal 4 (1d4 + 2) damage on a hit. The GM determines whether you use the static number or the die expression in parentheses; you don't use both."},
  {"id": "glossary_study", "name": "Study", "tag": "Action", "text": "When you take the Study action, you make an Intelligence check to study your memory, a book, a clue, or another source of knowledge and call to mind an important piece of information about it.\n\nThe Areas of Knowledge table suggests which skills are applicable to various areas of knowledge.\n\nAreas of Knowledge\n\nSkill\n\nAreas\n\nArcana\n\nSpells, magic items, eldritch symbols, magical traditions, planes of existence, and certain creatures (Aberrations, Constructs, Elementals, Fey, and Monstrosities)\n\nHistory\n\nHistoric events and people, ancient civilizations, wars, and certain creatures (Giants and Humanoids)\n\nInvestigation Traps, ciphers, riddles, and gadgetry\n\nNature\n\nTerrain, flora, weather, and certain creatures (Beasts, Dragons, Oozes, and Plants)\n\nReligion\n\nDeities, religious hierarchies and rites, holy symbols, cults, and certain creatures (Celestials, Fiends, and Undead)"},
  {"id": "glossary_stunned", "name": "Stunned", "tag": "Condition", "text": "While you have the Stunned condition, you experience the following effects.\n\nIncapacitated. You have the Incapacitated condition.\n\nSaving Throws Affected. You automatically fail Strength and Dexterity saving throws.\n\nAttacks Affected. Attack rolls against you have Advantage."},
  {"id": "glossary_suffocation", "name": "Suffocation", "tag": "Hazard", "text": "A creature can hold its breath for a number of minutes equal to 1 plus its Constitution modifier (minimum of 30 seconds) before suffocation begins. When a creature runs out of breath or is choking, it gains 1 Exhaustion level at the end of each of its turns. When a creature can breathe again, it removes all levels of Exhaustion it gained from suffocating."},
  {"id": "glossary_surprise", "name": "Surprise", "tag": "", "text": "If a creature is caught unawares by the start of combat, that creature is surprised, which causes it to have Disadvantage on its Initiative roll. See also \"Playing the Game\" (\"Combat\")."},
  {"id": "glossary_swimming", "name": "Swimming", "tag": "", "text": "While you're swimming, each foot of movement costs 1 extra foot (2 extra feet in Difficult Terrain). You ignore this extra cost if you have a Swim Speed and use it to swim. At the GM's option, moving any distance in rough water might require a successful DC 15 Strength (Athletics) check."},
  {"id": "glossary_swim_speed", "name": "Swim Speed", "tag": "", "text": "A Swim Speed can be used to swim without expending the extra movement normally associated with swimming. See also \"Swimming\" and \"Speed.\""},
  {"id": "glossary_target", "name": "Target", "tag": "", "text": "A target is the creature or object targeted by an attack roll, forced to make a saving throw by an effect, or selected to receive the effects of a spell or another phenomenon."},
  {"id": "glossary_telepathy", "name": "Telepathy", "tag": "", "text": "Telepathy is a magical ability that allows a creature to communicate mentally with another creature within a specified range. Unless a rule states otherwise, the contacted creature doesn't need to share a language with the telepath to understand this communication, but the contacted creature must be able to understand at least one language or be telepathic itself to understand.\n\nA telepath doesn't need to see a contacted creature, and the telepath can start or end the telepathic contact at any time (no action required). Telepathic contact can't be initiated and is immediately broken if either the telepath or the other creature has the Incapacitated condition. Telepathic contact is also broken if the contacted creature is no longer within the telepathy's range or if the telepath contacts a different creature within range.\n\nA creature without telepathy can receive telepathic messages but can't initiate a telepathic conversation. Once a telepathic conversation starts, the non-telepath can communicate mentally to the telepath until the telepathic connection ends."},
  {"id": "glossary_teleportation", "name": "Teleportation", "tag": "", "text": "Teleportation is a special kind of magical transportation. If you teleport, you disappear and reappear elsewhere instantly, without moving through the intervening space. This transportation doesn't expend movement unless a rule tells you otherwise, and teleportation never provokes Opportunity Attacks.\n\nWhen you teleport, all the equipment you're wearing and carrying teleports with you. If you're touching another creature when you teleport, that creature doesn't teleport with you unless the teleportation effect says otherwise.\n\nIf the destination space of your teleportation is occupied by another creature or blocked by a solid obstacle, you instead appear in the nearest unoccupied space of your choice.\n\nThe description of a teleportation effect tells you if you must see the teleportation's destination."},
  {"id": "glossary_temporary_hit_points", "name": "Temporary Hit Points", "tag": "", "text": "Temporary Hit Points are granted by certain effects and act as a buffer against losing real Hit Points. See also \"Playing the Game\" (\"Damage and Healing\")."},
  {"id": "glossary_tremorsense", "name": "Tremorsense", "tag": "", "text": "A creature with Tremorsense can pinpoint the location of creatures and moving objects within a specific range, provided that the creature with Tremorsense and anything it is detecting are both in contact with the same surface (such as the ground, a wall, or a ceiling) or the same liquid.\n\nTremorsense can't detect creatures or objects in the air, and it doesn't count as a form of sight."},
  {"id": "glossary_truesight", "name": "Truesight", "tag": "", "text": "If you have Truesight, your vision is enhanced within a specified range. Within that range, your vision pierces through the following:\n\nDarkness. You can see in normal and magical Darkness.\n\nInvisibility. You see creatures and objects that have the Invisible condition.\n\nVisual Illusions. Visual illusions appear transparent to you, and you automatically succeed on saving throws against them.\n\nTransformations. You discern the true form of any creature or object you see that has been transformed by magic.\n\nEthereal Plane. You see into the Ethereal Plane."},
  {"id": "glossary_unarmed_strike", "name": "Unarmed Strike", "tag": "", "text": "Instead of using a weapon to make a melee attack, you can use a punch, kick, headbutt, or similar forceful blow. In game terms, this is an Unarmed Strike--a melee attack that involves you using your body to damage, grapple, or shove a target within 5 feet of you.\n\nWhenever you use your Unarmed Strike, choose one of the following options for its effect.\n\nDamage. You make an attack roll against the target. Your bonus to the roll equals your Strength modifier plus your Proficiency Bonus. On a hit, the target takes Bludgeoning damage equal to 1 plus your Strength modifier.\n\nGrapple. The target must succeed on a Strength or Dexterity saving throw (it chooses which), or it has the Grappled condition. The DC for the saving throw and any escape attempts equals 8 plus your Strength modifier and Proficiency Bonus. This grapple is possible only if the target is no more than one size larger than you and if you have a hand free to grab it. See also \"Grappling.\"\n\nShove. The target must succeed on a Strength or Dexterity saving throw (it chooses which), or you either push it 5 feet away or cause it to have the Prone condition. The DC for the saving throw equals 8 plus your Strength modifier and Proficiency Bonus. This shove is possible only if the target is no more than one size larger than you."},
  {"id": "glossary_unconscious", "name": "Unconscious", "tag": "Condition", "text": "While you have the Unconscious condition, you experience the following effects.\n\nInert. You have the Incapacitated and Prone conditions, and you drop whatever you're holding. When this condition ends, you remain Prone.\n\nSpeed 0. Your Speed is 0 and can't increase. Attacks Affected. Attack rolls against you have Advantage. Saving Throws Affected. You automatically fail Strength and Dexterity saving throws. Automatic Critical Hits. Any attack roll that hits you is a Critical Hit if the attacker is within 5 feet of you. Unaware. You're unaware of your surroundings."},
  {"id": "glossary_unoccupied_space", "name": "Unoccupied Space", "tag": "", "text": "A space is unoccupied if no creatures are in it and it isn't completely filled by objects."},
  {"id": "glossary_utilize", "name": "Utilize", "tag": "Action", "text": "You normally interact with an object while doing something else, such as when you draw a sword as part of the Attack action. When an object requires an action for its use, you take the Utilize action."},
  {"id": "glossary_vulnerability", "name": "Vulnerability", "tag": "", "text": "If you have Vulnerability to a damage type, damage of that type is doubled against you. Vulnerability is applied only once to an instance of damage. See also \"Playing the Game\" (\"Damage and Healing\")."},
  {"id": "glossary_weapon", "name": "Weapon", "tag": "", "text": "A weapon is an object that is in the Simple or Martial weapon category. See also \"Equipment\" (\"Weapons\")."},
  {"id": "glossary_weapon_attack", "name": "Weapon Attack", "tag": "", "text": "A weapon attack is an attack roll made with a weapon. See also \"Weapon.\""},
];

export const TOOLBOX_2024: RuleEntry[] = [
  {"id": "toolbox_travel_pace", "name": "Travel Pace", "tag": "", "text": "A group of characters can travel overland at a Normal, Fast, or Slow pace, as described in \"Playing the Game.\" During any journey stage, the predominant terrain determines the characters' maximum travel pace, as shown in the Maximum Pace column of the Travel Terrain table. Certain factors can affect a group's travel pace."},
  {"id": "toolbox_good_roads", "name": "Good Roads", "tag": "", "text": "The presence of a good road increases the group's maximum pace by one step (from Slow to Normal or from Normal to Fast)."},
  {"id": "toolbox_slower_travelers", "name": "Slower Travelers", "tag": "", "text": "The group must move at a Slow pace if any group member's Speed is reduced to half or less of normal."},
  {"id": "toolbox_extended_travel", "name": "Extended Travel", "tag": "", "text": "Characters can push themselves to travel for more than 8 hours per day, at the risk of tiring. At the end of each additional hour of travel beyond 8 hours, each character must succeed on a Constitution saving throw or gain 1 Exhaustion level. The DC is 10 plus 1 for each hour past 8 hours."},
  {"id": "toolbox_special_movement", "name": "Special Movement", "tag": "", "text": "If a party can travel at a high Speed for an extended time, as with a spell such as Wind Walk or a magic item such as a Carpet of Flying, translate the party's Speed into travel rates using these rules:\n\nMiles per hour = Speed ÷ 10 Miles per day (Normal pace) = Miles per hour\n\n× number of hours traveled (typically 8) Fast pace = Miles per day × 1 (round down) Slow pace = Miles per day × 2/3 (round down)\n\nIf the characters are flying or their special movement allows them to ignore Difficult Terrain, they can move at a Fast pace regardless of the terrain."},
  {"id": "toolbox_vehicles", "name": "Vehicles", "tag": "", "text": "Characters traveling in a vehicle use the vehicle's speed in miles per hour (as shown in \"Equipment\") to determine their rate of travel, and they don't choose a travel pace."},
  {"id": "toolbox_creating_a_background", "name": "Creating a Background", "tag": "", "text": "A character's background represents what the character did prior to becoming an adventurer. Creating a unique background or customizing an existing one can reflect the particular theme of your campaign or elements of your world. You can also create a background to help a player craft the story they have in mind for their character.\n\nThis section describes, step by step, how you can create backgrounds tailored for your world and the heroes in it."},
  {"id": "toolbox_1_choose_abilities", "name": "1: Choose Abilities", "tag": "", "text": "Choose three abilities that seem appropriate for the background:\n\nStrength or Dexterity. These abilities are ideal for a background involving physical exertion.\n\nConstitution. This ability is ideal for a background that involves endurance or long hours of activity.\n\nTravel Terrain\n\nTerrain\n\nMaximum Pace\n\nArctic\n\nFast*\n\nCoastal\n\nNormal\n\nDesert\n\nNormal\n\nForest\n\nNormal\n\nGrassland\n\nFast\n\nHill\n\nNormal\n\nMountain\n\nSlow\n\nSwamp\n\nSlow\n\nUnderdark\n\nNormal\n\nUrban\n\nNormal\n\nWaterborne Special\n\nEncounter Distance 6d6 × 10 feet 2d10 × 10 feet 6d6 × 10 feet 2d8 × 10 feet 6d6 × 10 feet 2d10 × 10 feet 4d10 × 10 feet 2d8 × 10 feet 2d6 × 10 feet 2d6 × 10 feet 6d6 × 10 feet\n\nForaging DC 20 10 20 10 15 15 20 10 20 20 15\n\nNavigation DC 10 5 10 15 5 10 15 15 10 15 10\n\n*Appropriate equipment (such as skis) is necessary to keep up a Fast pace in Arctic terrain. Characters' rate of travel while waterborne depends on the vehicle carrying them; see \"Vehicles.\"\n\nSearch DC 10 15 10 15 15 15 20 20 20 15 15\n\nIntelligence or Wisdom. One or both abilities are ideal for a background that focuses on cerebral or spiritual matters.\n\nCharisma. This ability is ideal for a background that involves performance or social interaction."},
  {"id": "toolbox_2_choose_a_feat", "name": "2: Choose a Feat", "tag": "", "text": "Choose one feat from the Origin category. See \"Origin Feats\" for examples of Origin feats."},
  {"id": "toolbox_3_choose_skill_proficiencies", "name": "3: Choose Skill Proficiencies", "tag": "", "text": "Choose two skills appropriate for the background. There needn't be a relationship between the skill proficiencies a background grants and the ability scores it increases."},
  {"id": "toolbox_4_choose_a_tool_proficiency", "name": "4: Choose a Tool Proficiency", "tag": "", "text": "Choose one tool used in the practice of the background or often associated with it."},
  {"id": "toolbox_5_choose_equipment", "name": "5: Choose Equipment", "tag": "", "text": "Assemble a package of equipment worth 50 GP (including unspent gold). Don't include Martial weapons or armor, as characters get them from their class choices."},
  {"id": "toolbox_curses_and_magical_contagions", "name": "Curses and Magical Contagions", "tag": "", "text": "A curse is a magical burden that lasts for a specified time or until it is ended by some means. A magical contagion is an adverse effect of magical origin that is contagious by definition.\n\nThe following sections discuss curses and magical contagions in detail."},
  {"id": "toolbox_curses", "name": "Curses", "tag": "", "text": "A curse typically takes one of the forms detailed below."},
  {"id": "toolbox_bestow_curse", "name": "Bestow Curse", "tag": "", "text": "The simplest curses are created by the Bestow Curse spell. The effects of such curses are limited and can be ended by the Remove Curse spell.\n\nBestow Curse provides useful benchmarks for gauging the potency of other curses. A curse that lasts for 1 minute equates to a level 3 spell, while one that lasts until dispelled equates to a level 9 spell."},
  {"id": "toolbox_cursed_creatures", "name": "Cursed Creatures", "tag": "", "text": "Some monsters are associated with curses, whether as part of their origins or due to their ability to spread curses--werewolves being a prime example.\n\nYou decide how a spell like Remove Curse affects a creature with accursed origins. For example, you might decide that a mummy was created through a curse and it can be destroyed permanently only by casting Remove Curse on its corpse."},
  {"id": "toolbox_cursed_magic_items", "name": "Cursed Magic Items", "tag": "", "text": "Cursed magic items are created deliberately or originate as the result of supernatural events. Such items are detailed in \"Magic Items.\""},
  {"id": "toolbox_narrative_curses", "name": "Narrative Curses", "tag": "", "text": "A curse might manifest during an adventure when a creature's violation of a taboo warrants supernatural punishment, such as breaking a vow, defiling a tomb, or murdering an innocent. Such a curse can have any effects you design, or it might be a customized version of another type of curse discussed in this section.\n\nA creature affected by such a curse should know why they're being punished and be able to learn how to end their curse, likely by symbolically righting the wrong they committed. How a spell like Remove Curse affects a curse that's part of your adventure is up to you--the spell might merely suppress the effects of the curse for a time. Regardless, narrative curses should feel like rare, potent magic rooted in the lore of your campaign."},
  {"id": "toolbox_environmental_curses", "name": "Environmental Curses", "tag": "", "text": "Some locations are so suffused with evil that anyone who lingers there is burdened with a curse. Demonic Possession is one example of an environmental curse.\n\nDemonic Possession. Demonic Possession arises from the chaos and evil of the Abyss and commonly besets creatures that interact with demonic objects or linger in desecrated locations, where demonic spirits await victims.\n\nA creature that becomes the target of Demonic Possession must succeed on a DC 15 Charisma saving throw or be possessed by a bodiless demonic entity. Whenever the possessed creature rolls a 1 on a D20 Test, the demonic entity takes control of the creature and determines the creature's behavior thereafter. At the end of each of the possessed creature's later turns, the creature makes a DC 15 Charisma saving throw, regaining control of itself on a success.\n\nAfter finishing a Long Rest, a creature with Demonic Possession makes a DC 15 Charisma saving throw. On a successful save, the effect ends on the creature. A Dispel Evil and Good spell or any magic that removes a curse also ends the effect on it."},
  {"id": "toolbox_magical_contagions", "name": "Magical Contagions", "tag": "", "text": "Alchemists, potion brewers, and areas of wild magic are credited with creating the first magical contagions. An outbreak of such a contagion can form the basis of an adventure as characters search for a cure and try to stop the contagion's spread."},
  {"id": "toolbox_rest_and_recuperation", "name": "Rest and Recuperation", "tag": "", "text": "If a creature infected with a magical contagion spends 3 days recuperating--engaging in no activities that would interrupt a Long Rest--the creature makes a DC 15 Constitution saving throw at the end of the recuperation period. On a successful save, the creature has Advantage on saving throws to fight off the magical contagion for the next 24 hours."},
  {"id": "toolbox_example_contagions", "name": "Example Contagions", "tag": "", "text": "The following examples show how magical contagions can work. Feel free to alter the saving throw DCs, effects, and other characteristics of these contagions to suit your campaign.\n\nCackle Fever\n\nMagical Contagion\n\nCheaply made potions and elixirs are sometimes tainted by Cackle Fever, which affects Humanoids only (gnomes are strangely immune). A creature suffers the following effects 1d4 days after infection:\n\nFever. The creature gains 1 Exhaustion level, which lasts until the contagion ends on the creature.\n\nUncontrollable Laughter. While the creature has the Exhaustion condition, the creature makes a DC 13 Constitution saving throw each time it takes damage other than Psychic damage. On a failed save, the creature takes 5 (1d10) Psychic damage and has the Incapacitated condition as it laughs uncontrollably. At the end of each of its turns, the creature repeats the save, ending the effect on itself on a success. After 1 minute, it succeeds automatically.\n\nFighting the Contagion. At the end of each Long Rest, an infected creature makes a DC 13 Constitution saving throw. After the creature succeeds on three of these saves, the contagion ends on it, and the creature is immune to Cackle Fever for 1 year.\n\nSpreading the Contagion. Any Humanoid (other than a gnome) that starts its turn within a 10-foot Emanation originating from a creature infected with Cackle Fever must succeed on a DC 10 Constitution saving throw or also become infected with the contagion. On a successful save, the Humanoid can't catch the contagion from that particular infected creature for the next 24 hours.\n\nSewer Plague\n\nMagical Contagion\n\nFouled potions and alchemical waste can give rise to Sewer Plague, which incubates in sewers and refuse heaps and is sometimes transmitted by creatures that dwell in such areas, including otyughs and rats. Any Humanoid that is wounded by a creature that carries the contagion or that comes into contact with contaminated filth or offal must succeed on a DC 11 Constitution saving throw or become infected with Sewer Plague. A creature suffers the following effects 1d4 days after infection:\n\nFatigue. The creature gains 1 Exhaustion level. Weakness. While the creature has any Exhaustion\n\nlevels, it regains only half the normal number of Hit Points from spending Hit Point Dice. Restlessness. While the creature has any Exhaustion levels, finishing a Long Rest neither restores lost Hit Points nor reduces the creature's Exhaustion level.\n\nFighting the Contagion. Daily at dawn, an infected creature makes a DC 11 Constitution saving throw. On a failed save, the creature gains 1 Exhaustion level as its fatigue worsens. On a successful save, the creature's Exhaustion level decreases by 1. If the creature's Exhaustion level is reduced to 0, the contagion ends on the creature.\n\nSight Rot\n\nMagical Contagion\n\nAny Beast or Humanoid that drinks water tainted by Sight Rot must succeed on a DC 15 Constitution saving throw or have the Blinded condition until the contagion ends.\n\nFighting the Contagion. Magic such as a Heal or Lesser Restoration spell ends the contagion immediately. A character who is proficient with an Herbalism Kit can use it to create one dose of nonmagical ointment, which takes 1 hour. When applied to the eyes of a creature suffering from Sight Rot, the ointment suppresses the contagion on that creature for 24 hours. If the contagion is suppressed in this way for a total of 72 hours (requiring three doses and applications of the ointment), the contagion ends on the creature.\n\nSpreading the Contagion. Any Humanoid that makes skin contact with a creature infected with Sight Rot must succeed on a DC 15 Constitution saving throw or also become infected with the contagion. On a successful save, the Humanoid can't catch the contagion from that particular infected creature for the next 24 hours.\n\nEnvironmental Effects"},
  {"id": "toolbox_deep_water", "name": "Deep Water", "tag": "", "text": "Swimming through deep water (more than 100 feet deep) presents additional challenges because of the water's pressure and cold temperature. After each hour of swimming in deep water, a creature that lacks a Swim Speed must succeed on a DC 10 Constitution saving throw or gain 1 Exhaustion level."},
  {"id": "toolbox_extreme_cold", "name": "Extreme Cold", "tag": "", "text": "When the temperature is 0 degrees Fahrenheit or lower, a creature exposed to the extreme cold must succeed on a DC 10 Constitution saving throw at the end of each hour or gain 1 Exhaustion level. Creatures that have Resistance or Immunity to Cold damage automatically succeed on the save."},
  {"id": "toolbox_extreme_heat", "name": "Extreme Heat", "tag": "", "text": "When the temperature is 100 degrees Fahrenheit or higher, a creature exposed to the extreme heat and without access to drinkable water must succeed on a Constitution saving throw at the end of each hour or gain 1 Exhaustion level. The DC is 5 for the first hour and increases by 1 for each additional hour. Creatures wearing Medium or Heavy armor have Disadvantage on the save. Creatures that have Resistance or Immunity to Fire damage automatically succeed on the save."},
  {"id": "toolbox_frigid_water", "name": "Frigid Water", "tag": "", "text": "A creature can be immersed in frigid water for a number of minutes equal to its Constitution score before suffering any ill effects. Each additional minute spent in frigid water requires the creature to succeed on a DC 10 Constitution saving throw or gain 1 Exhaustion level. Creatures with Resistance or Immunity to Cold damage automatically succeed on the save, as do creatures that are naturally adapted to living in ice-cold water."},
  {"id": "toolbox_heavy_precipitation", "name": "Heavy Precipitation", "tag": "", "text": "Everything within an area of heavy rain or heavy snowfall is Lightly Obscured, and creatures in the area have Disadvantage on all Wisdom (Perception) checks. Heavy rain also extinguishes open flames."},
  {"id": "toolbox_high_altitude", "name": "High Altitude", "tag": "", "text": "Traveling at altitudes of 10,000 feet or higher above sea level is taxing for most creatures because of the reduced amount of oxygen in the air. Each hour such a creature spends traveling at high altitude counts as 2 hours for the purpose of determining how long that creature can travel (see \"Travel Pace\").\n\nCreatures can become acclimated to a high altitude by spending 30 days or more at this elevation. Creatures can't become acclimated to elevations above 20,000 feet unless they are native to such environments."},
  {"id": "toolbox_slippery_ice", "name": "Slippery Ice", "tag": "", "text": "Slippery ice is Difficult Terrain. A creature that moves onto slippery ice for the first time on a turn or starts its turn there must succeed on a DC 10 Dexterity saving throw or have the Prone condition."},
  {"id": "toolbox_strong_wind", "name": "Strong Wind", "tag": "", "text": "Strong wind imposes Disadvantage on ranged attack rolls with weapons. It also extinguishes open flames and disperses fog. A flying creature in a strong wind must land at the end of its turn or fall.\n\nA strong wind in a desert can create a sandstorm that imposes Disadvantage on Wisdom (Perception) checks."},
  {"id": "toolbox_thin_ice", "name": "Thin Ice", "tag": "", "text": "Thin ice has a weight tolerance of 3d10 × 10 pounds per 10-foot-square area. Whenever the total weight on an area of thin ice exceeds its tolerance, the ice in that area breaks. All creatures on broken ice fall through. Below the ice is frigid water (see \"Frigid Water\" above)."},
  {"id": "toolbox_fear_and_mental_stress", "name": "Fear and Mental Stress", "tag": "", "text": "Due to the nature of their vocation, adventurers tend to be less susceptible to fear and mental stress than common folk. Whereas a farmer might flee in terror from a bear or an apparition, adventurers are made of sterner stuff. That said, certain creatures and game effects can terrify or fray the mind of even the most stalwart adventurer.\n\nIf you plan to use any of these rules, discuss them with your players at the start of the campaign."},
  {"id": "toolbox_fear_effects", "name": "Fear Effects", "tag": "", "text": "Whenever the characters encounter something that is supernaturally frightful, use the Frightened condition as the baseline effect. Fear effects typically require a Wisdom saving throw, with a save DC based on how terrifying the situation is. The Sample Fear DCs table provides some examples."},
  {"id": "toolbox_sample_fear_dcs", "name": "Sample Fear DCs", "tag": "", "text": "Example When the characters open a sarcophagus, a harmless yet terrifying apparition appears.\n\nA character triggers a magical trap that creates an illusory manifestation of that character's worst fears, visible only to that character.\n\nA portal to the Abyss opens, revealing a nightmarish realm of torment and slaughter.\n\nSave DC 10 15\n\nTypically, a Frightened creature repeats the saving throw at the end of each of its turns, ending the effect on itself on a success.\n\nAt your discretion, a Frightened creature might be subject to other effects as long as the Frightened condition lasts. Consider these examples:\n\n• The Frightened creature must take the Dash action on each of its turns and uses its movement to get farther away from the source of its fear.\n\n• Attack rolls against the Frightened creature have Advantage.\n\n• The Frightened creature can do only one of the following on each of its turns: move, take an action, or take a Bonus Action."},
  {"id": "toolbox_mental_stress_effects", "name": "Mental Stress Effects", "tag": "", "text": "When a character is subjected to an effect that causes intense mental stress, Psychic damage is the best way to emulate that effect.\n\nThe Sample Mental Stress Effects table provides a few examples of such effects, with suggested saving throw DCs and damage. Mental stress can usually be resisted with a successful Wisdom save, but sometimes an Intelligence or Charisma save is more appropriate. On a successful save, a character might take half as much damage instead of no damage, at your discretion."},
  {"id": "toolbox_sample_mental_stress_effects", "name": "Sample Mental Stress Effects", "tag": "", "text": "Example A character ingests a hallucinogenic substance that distorts the character's perception of reality. A character touches a fiendish idol that tears at the character's mind, threatening to shatter it. A magical trap flings a character into the Far Realm until the end of that character's next turn.\n\nSave Psychic DC Damage 10 1d6\n\n15 3d6\n\n20 9d6"},
  {"id": "toolbox_prolonged_effects", "name": "Prolonged Effects", "tag": "", "text": "Exposure to mental stress can cause prolonged effects. Consider the following possibilities.\n\nShort-Term Effects. The character has the Frightened, Incapacitated, or Stunned condition for 1d10 minutes. This condition might be accompanied by alarming behavior or hallucinations. These effects can be suppressed with the Calm Emotions spell or removed by the Lesser Restoration spell.\n\nLong-Term Effects. The character has Disadvantage on some or all ability checks for 1d10 × 10 hours, stemming from an unwillingness or inability to exert a particular set of abilities. The character might feel enervated and unable to exert much Strength, for example, or become so suspicious of others that Charisma checks are more difficult. These effects can be suppressed with the Calm Emotions spell or removed by the Lesser Restoration spell.\n\nIndefinite Effects. An indefinite effect is a longterm effect (see above) that lasts until removed by a Greater Restoration spell. It can be suppressed by a Calm Emotions spell."},
  {"id": "toolbox_poison", "name": "Poison", "tag": "", "text": "Given their insidious and deadly nature, poisons are a favorite tool among assassins and evil creatures.\n\nPoisons come in the following four types:\n\nContact. Contact poison can be smeared on an object and remains potent until it is touched or washed off. A creature that touches contact poison with exposed skin suffers its effects.\n\nIngested. A creature must swallow an entire dose of ingested poison to suffer its effects. The dose can be delivered in food or a liquid. You may decide that a partial dose has a reduced effect, such as allowing Advantage on the saving throw or dealing only half as much damage on a failed save.\n\nInhaled. Poisonous powders and gases take effect when inhaled. Blowing the powder or releasing the gas subjects creatures in a 5-foot Cube to its effect. The resulting cloud dissipates immediately afterward. Holding one's breath is ineffective against inhaled poisons, as they affect nasal membranes, tear ducts, and other parts of the body.\n\nInjury. Injury poison can be applied as a Bonus Action to a weapon, a piece of ammunition, or similar object. The poison remains potent until delivered through a wound or washed off. A creature that takes Piercing or Slashing damage from an object coated with the poison is exposed to its effects."},
  {"id": "toolbox_purchasing_poison", "name": "Purchasing Poison", "tag": "", "text": "In some settings, laws prohibit the possession and use of poison, but an illicit dealer or unscrupulous apothecary might keep a hidden stash. Characters with criminal contacts might be able to acquire poison easily. Other characters might have to make extensive inquiries and pay bribes before they acquire the poison they seek."},
  {"id": "toolbox_harvesting_poison", "name": "Harvesting Poison", "tag": "", "text": "A character can attempt to harvest poison from a venomous creature that is dead or has the Incapacitated condition. The effort takes 1d6 minutes, after which the character makes a DC 20 Intelligence (Nature) check using a Poisoner's Kit. On a successful check, the character harvests enough poison for a single dose, and no additional poison can be harvested from that creature. On a failed check, the character is unable to extract any poison. If the character fails the check by 5 or more, the character is subjected to the creature's poison."},
  {"id": "toolbox_sample_poisons", "name": "Sample Poisons", "tag": "", "text": "Example poisons are detailed here in alphabetical order. Each poison's description includes the suggested price for a single dose of the poison, its type (contact, ingested, inhaled, or injury), and a description of the poison's debilitating effects.\n\nAssassin's Blood (150 GP)"},
  {"id": "toolbox_ingested_poison", "name": "Ingested Poison", "tag": "", "text": "A creature subjected to Assassin's Blood makes a DC 10 Constitution saving throw. On a failed save, the creature takes 6 (1d12) Poison damage and has the Poisoned condition for 24 hours. On a successful save, the creature takes half as much damage only.\n\nBurnt Othur Fumes (500 GP)"},
  {"id": "toolbox_inhaled_poison", "name": "Inhaled Poison", "tag": "", "text": "A creature subjected to Burnt Othur Fumes must succeed on a DC 13 Constitution saving throw or take 10 (3d6) Poison damage, and it must repeat the save at the start of each of its turns. On each successive failed save, the creature takes 3 (1d6) Poison damage. After three successful saves, the poison ends.\n\nCrawler Mucus (200 GP)"},
  {"id": "toolbox_contact_poison", "name": "Contact Poison", "tag": "", "text": "A creature subjected to Crawler Mucus must succeed on a DC 13 Constitution saving throw or have the Poisoned condition for 1 minute. The creature also has the Paralyzed condition while Poisoned in this way. The creature repeats the save at the end of each of its turns, ending the effect on itself on a success.\n\nEssence of Ether (300 GP)"},
  {"id": "toolbox_inhaled_poison_2", "name": "Inhaled Poison", "tag": "", "text": "A creature subjected to Essence of Ether must succeed on a DC 15 Constitution saving throw or have the Poisoned condition for 8 hours. The creature also has the Unconscious condition while Poisoned in this way. The creature wakes up if it takes damage or if another creature takes an action to shake it awake.\n\nMalice (250 GP)"},
  {"id": "toolbox_inhaled_poison_3", "name": "Inhaled Poison", "tag": "", "text": "A creature subjected to Malice must succeed on a DC 15 Constitution saving throw or have the Poisoned condition for 1 hour. The creature also has the Blinded condition while Poisoned in this way.\n\nMidnight Tears (1,500 GP)"},
  {"id": "toolbox_ingested_poison_2", "name": "Ingested Poison", "tag": "", "text": "A creature that ingests Midnight Tears suffers no effect until the stroke of midnight. Any effect that\n\nends the Poisoned condition neutralizes this poison. If the poison hasn't been neutralized before midnight, the creature makes a DC 17 Constitution saving throw, taking 31 (9d6) Poison damage on a failed save or half as much damage on a successful one.\n\nOil of Taggit (400 GP)"},
  {"id": "toolbox_contact_poison_2", "name": "Contact Poison", "tag": "", "text": "A creature subjected to Oil of Taggit must succeed on a DC 13 Constitution saving throw or have the Poisoned condition for 24 hours. The creature also has the Unconscious condition while Poisoned in this way. It wakes up if it takes damage.\n\nPale Tincture (250 GP)"},
  {"id": "toolbox_ingested_poison_3", "name": "Ingested Poison", "tag": "", "text": "A creature subjected to Pale Tincture must succeed on a DC 16 Constitution saving throw or take 3 (1d6) Poison damage and have the Poisoned condition. The Poisoned creature repeats the save every 24 hours, taking 3 (1d6) Poison damage on a failed save. The damage the poison deals can't be healed by any means while the creature remains Poisoned. After seven successful saves against the poison, the creature is no longer Poisoned.\n\nPurple Worm Poison (2,000 GP)"},
  {"id": "toolbox_injury_poison", "name": "Injury Poison", "tag": "", "text": "A creature subjected to Purple Worm Poison makes a DC 21 Constitution saving throw, taking 35 (10d6) Poison damage on a failed save or half as much damage on a successful one.\n\nSerpent Venom (200 GP)"},
  {"id": "toolbox_injury_poison_2", "name": "Injury Poison", "tag": "", "text": "A creature subjected to Serpent Venom must succeed on a DC 11 Constitution saving throw, taking\n\n10 (3d6) Poison damage on a failed save or half as much damage on a successful one.\n\nSpider's Sting (200 GP)"},
  {"id": "toolbox_injury_poison_3", "name": "Injury Poison", "tag": "", "text": "A creature subjected to Spider's Sting must succeed on a DC 13 Constitution saving throw or have the Poisoned condition for 1 hour. If the creature fails the save by 5 or more, the creature also has the Unconscious condition while Poisoned in this way. The creature wakes up if it takes damage or if another creature takes an action to shake it awake.\n\nTorpor (600 GP)"},
  {"id": "toolbox_ingested_poison_4", "name": "Ingested Poison", "tag": "", "text": "A creature subjected to Torpor poison must succeed on a DC 15 Constitution saving throw or have the Poisoned condition for 4d6 hours. The creature's Speed is halved while the creature is Poisoned in this way.\n\nTruth Serum (150 GP)"},
  {"id": "toolbox_ingested_poison_5", "name": "Ingested Poison", "tag": "", "text": "A creature subjected to Truth Serum must succeed on a DC 11 Constitution saving throw or have the Poisoned condition for 1 hour. The Poisoned creature can't knowingly communicate a lie.\n\nWyvern Poison (1,200 GP)"},
  {"id": "toolbox_injury_poison_4", "name": "Injury Poison", "tag": "", "text": "A creature subjected to Wyvern Poison makes a DC 14 Constitution saving throw, taking 24 (7d6) Poison damage on a failed save or half as much damage on a successful one."},
  {"id": "toolbox_traps", "name": "Traps", "tag": "", "text": "Traps should be used sparingly, lest they lose their charm. A hidden pit can be a fun surprise, but too many traps in an adventure can lead players to become overly cautious, which slows down the game.\n\nThe best traps are fleeting distractions that skilled characters can overcome in a short amount of time or deadly puzzles that require quick thinking and teamwork to overcome. Traps that are undetectable and inescapable are rarely fun."},
  {"id": "toolbox_parts_of_a_trap", "name": "Parts of a Trap", "tag": "", "text": "The description of a trap includes the following parts after the trap's name:\n\nSeverity and Levels. A trap is designated as a nuisance or as deadly for characters of certain levels. A nuisance trap is unlikely to seriously harm characters of the indicated levels, whereas a deadly trap can grievously damage characters of the indicated levels.\n\nTrigger. Traps are often set to go off when a creature enters an area or touches an object. Examples of triggers include stepping on a pressure plate, crossing a trip wire, turning a doorknob, or using the wrong key in a lock.\n\nDuration. Some traps have durations expressed in rounds, minutes, or hours. Others specify that their effects last until the trap is destroyed or dispelled. If a trap's duration is instantaneous, its effect is resolved instantly. If a trap resets after activating, that fact is noted in this entry. A trap is otherwise inert after activation.\n\nUse caution when introducing a trap to characters of a level lower than the trap's level range. A trap that is a nuisance at one level range could be deadly to characters of a lower level range."},
  {"id": "toolbox_example_traps", "name": "Example Traps", "tag": "", "text": "Traps are presented in alphabetical order.\n\nCollapsing Roof\n\nDeadly Trap (Levels 1–4)\n\nTrigger: A creature crosses a trip wire Duration: Instantaneous\n\nThis trap uses a trip wire to collapse an unstable section of ceiling. The trip wire is 3 inches off the ground and stretches between two weak supports that topple when the trip wire is pulled.\n\nThe first creature that crosses the trip wire causes the supports to topple and the unstable section of ceiling to collapse. Each creature beneath the unstable section of ceiling must succeed on a DC 13 Dexterity saving throw, taking 11 (2d10) Bludgeoning damage on a failed save or half as much damage\n\non a successful one. Rubble from the collapse turns the trapped area into Difficult Terrain.\n\nDetect and Disarm. As a Search action, a creature can examine the trapped area and make a DC 11 Wisdom (Perception) check, detecting the trip wire and the unstable section of ceiling on a successful check. Once detected, the trip wire can be easily cut or avoided (no ability check required).\n\nAt Higher Levels. You can scale the trap for higher levels by increasing the damage and the save DC, as shown in the following table.\n\nLevels\n\nBludgeoning Damage\n\nSave DC\n\n5–10\n\n22 (4d10)\n\n11–16\n\n55 (10d10)\n\n17–20\n\n99 (18d10)"},
  {"id": "toolbox_falling_net", "name": "Falling Net", "tag": "", "text": "Nuisance Trap (Levels 1–4)\n\nTrigger: A creature crosses a trip wire Duration: Instantaneous\n\nA falling net trap uses a trip wire to release a weighted, 10-foot-square Net suspended from the ceiling. The trip wire is 3 inches off the ground and stretches between two columns or trees.\n\nThe first creature that crosses the trip wire causes the Net to fall on it. The target must succeed on a DC 10 Dexterity saving throw or have the Restrained condition until it escapes. The target succeeds automatically if it's Huge or larger. A creature can take an action to make a DC 10 Strength (Athletics) check, freeing itself or another creature within its reach from the Net on a successful check.\n\nDetect and Disarm. As a Search action, a creature can examine the trapped area and make a DC 11 Wisdom (Perception) check, detecting the trip wire and the suspended Net on a successful check. Once detected, the trip wire can be easily cut or avoided (no ability check required).\n\nDestroy the Net. Reducing the Net to 0 Hit Points frees any creature trapped in it (see \"Adventuring Gear\" for the Net's statistics).\n\nSet the Trap. A creature that has Thieves' Tools and all the trap's components (including a Net) can try to set a falling net trap, doing so with a successful DC 13 Dexterity (Sleight of Hand) check. Each attempt to set this trap takes 10 minutes.\n\nAt Higher Levels. You can scale the trap for higher levels by increasing the weight of the Net, which increases the save DC and the DC of the Strength (Athletics) check as follows: DC 12 at levels 5–10, DC 14 at levels 11–16, or DC 16 at levels 17–20.\n\nFire-Casting Statue\n\nDeadly Trap (Levels 1–4)\n\nTrigger: A creature moves onto a pressure plate\n\nDuration: Instantaneous, and the trap resets at the start of the next turn\n\nWhen a creature moves onto this trap's pressure plate for the first time on a turn or starts its turn there, a nearby statue exhales a 15-foot Cone of magical flame. The statue can look like anything, such as a dragon or a wizard. Each creature in the Cone must succeed on a DC 15 Dexterity saving throw, taking 11 (2d10) Fire damage on a failed save or half as much damage on a successful one.\n\nDetect and Disarm. A Detect Magic spell reveals an aura of Evocation magic around the statue. As a Search action, a creature within 5 feet of the statue can examine it and make a DC 10 Wisdom (Perception) check, detecting a tiny glyph on the statue on a successful check. Once the glyph is found, a character can take a Study action to examine it and make a DC 15 Intelligence (Arcana) check, ascertaining that the glyph means \"fire\" on a successful check. As an action, a character can use a sharp tool to deface the glyph, which disarms the trap.\n\nAs a Search action, a creature can examine the section of floor that forms the pressure plate and make a DC 15 Wisdom (Perception) check, detecting the pressure plate on a successful check. Wedging an Iron Spike or similar object under the pressure plate prevents the trap from triggering.\n\nAt Higher Levels. You can scale the trap for higher levels by increasing the damage and the area of effect, as shown in the following table.\n\nLevels Fire Damage Area of Effect\n\n5–10\n\n22 (4d10)\n\n30-foot Cone\n\n11–16\n\n55 (10d10) 60-foot Cone\n\n17–20\n\n99 (18d10) 120-foot Cone"},
  {"id": "toolbox_hidden_pit", "name": "Hidden Pit", "tag": "", "text": "Nuisance Trap (Levels 1–4)\n\nTrigger: A creature moves onto the pit's lid Duration: Instantaneous\n\nThis 10-foot-deep pit has a hinged lid constructed from material identical to the surrounding floor. When a creature moves onto the lid, it swings open like a trapdoor, causing the creature to fall into the pit. The lid remains open thereafter.\n\nA creature that falls into the pit takes 3 (1d6) Bludgeoning damage from the fall.\n\nDetect and Disarm. As a Study action, a creature can examine the section of floor that forms the pit's lid and make a DC 15 Intelligence (Investigation) check, detecting the pit on a successful check. Once the pit is detected, an Iron Spike or a similar object can be wedged between the pit's lid and the surrounding floor to prevent the lid from opening, thereby making it safe to cross. The cover can also be held shut using Arcane Lock or similar magic.\n\nEscape. A creature needs a Climb Speed, climbing gear, or magic such as Spider Climb to scale the pit's smooth walls. You can make the pit easier to escape by adding cracks in the walls big enough to serve as handholds and footholds.\n\nAt Higher Levels. You can scale the trap for higher levels by increasing the pit's depth and damage, as shown in the following table.\n\nLevels\n\nPit Depth\n\nBludgeoning Damage\n\n5–10\n\n30 feet\n\n10 (3d6)\n\n11–16\n\n60 feet\n\n21 (6d6)\n\n17–20\n\n120 feet\n\n42 (12d6)\n\nPoisoned Darts\n\nDeadly Trap (Levels 1–4)\n\nTrigger: A creature moves onto a pressure plate Duration: Instantaneous, and the trap resets at the\n\nstart of the next turn if it has activated fewer than three times\n\nWhen a creature moves onto this trap's pressure plate for the first time on a turn, poisoned darts shoot from tubes embedded in the surrounding walls. The holes that house these tubes are obscured by dust and cobwebs or skillfully hidden amid bas-reliefs, murals, or frescoes.\n\nEach creature in the darts' path must succeed on a DC 13 Dexterity saving throw or be struck by 1d3 darts, taking 3 (1d6) Poison damage per dart.\n\nDetect and Disarm. As a Search action, a creature can examine the walls and make a DC 15 Wisdom (Perception) check, detecting the holes on a successful check. Plugging all the holes with wax, cloth, or detritus prevents the darts from firing.\n\nAs a Search action, a creature can examine the section of floor that forms the pressure plate and make a DC 15 Wisdom (Perception) check, detecting the pressure plate on a successful check. Wedging an Iron Spike or a similar object under the pressure plate prevents the trap from triggering.\n\nAt Higher Levels. You can scale the trap for higher levels by increasing each dart's Poison damage as follows: 7 (2d6) at levels 5–10, 14 (4d6) at levels 11–16, or 24 (7d6) at levels 17–20."},
  {"id": "toolbox_poisoned_needle", "name": "Poisoned Needle", "tag": "", "text": "Nuisance Trap (Levels 1–4)\n\nTrigger: A creature opens the trap's lock improperly or fails to disarm the trap\n\nDuration: Instantaneous\n\nA poisoned needle is hidden in a lock. When a creature opens the lock with any object other than the proper key, the needle springs out and stabs the creature. The creature makes a DC 11 Constitution saving throw. On a failed save, the creature takes 5 (1d10) Poison damage and has the Poisoned\n\ncondition for 1 hour. On a successful save, the creature takes half as much damage only.\n\nAvoid. The trap doesn't trigger if the lock is opened using a Knock spell or similar magic.\n\nDetect and Disarm. As a Search action, a creature can examine the trapped lock and make a DC 15 Wisdom (Perception) check, detecting the needle on a successful check. Once the trap is detected, a character can take an action to try to disarm the trap, doing so with a successful DC 15 Dexterity (Sleight of Hand) check. On a failed check, the creature triggers the trap.\n\nAt Higher Levels. You can scale the trap for higher levels by increasing the damage and the save DC, as shown in the following table.\n\nLevels Poison Damage\n\nSave DC\n\n5–10\n\n11 (2d10)\n\n11–16\n\n22 (4d10)\n\n17–20\n\n55 (10d10)"},
  {"id": "toolbox_rolling_stone", "name": "Rolling Stone", "tag": "", "text": "Deadly Trap (Levels 11–16) or Nuisance Trap (Levels 17–20)\n\nTrigger: A creature moves onto a pressure plate Duration: Until the stone stops rolling\n\nWhen a creature moves onto a hidden pressure plate, a 5-foot-radius orb of solid stone is released from a secret compartment and begins to roll. The stone and all creatures nearby roll Initiative; the stone gets a +8 bonus on its Initiative roll.\n\nOn its turn, the stone moves 60 feet in one direction, changing course if redirected by an obstacle. The stone can move through creatures' spaces, and creatures can move through the stone's space, treating it as Difficult Terrain. Whenever the stone enters a creature's space for the first time on a turn or a creature enters the stone's space while the stone is rolling, that creature must succeed on a DC 15 Dexterity saving throw or take 55 (10d10) Bludgeoning damage and have the Prone condition.\n\nThe stone stops when it hits a wall or similar barrier. It can't go around corners, but creative dungeon builders incorporate curving turns into nearby passages that allow the stone to keep moving.\n\nDetect and Disarm. As a Study action, a creature can examine the section of floor that forms the pressure plate and make a DC 15 Intelligence (Investigation) check, deducing the pressure plate's function on a successful check. Wedging an Iron Spike or a similar object under the pressure plate prevents the trap from triggering.\n\nDestroy the Stone. The stone is a Large object that has AC 17, HP 100, a Damage Threshold of 10, and Immunity to Poison and Psychic damage.\n\nSlow the Stone. As an action, a creature can try to slow down the stone with a DC 20 Strength (Athletics) check. If the check is successful, the distance the stone moves on its turn is reduced by 15 feet. If that distance drops to 0, it stops moving and is no longer a threat.\n\nSpiked Pit\n\nDeadly Trap (Levels 1–4)\n\nTrigger: A creature moves onto the pit's lid Duration: Instantaneous\n\nA 10-foot-deep pit has a hinged lid constructed from material identical to the surrounding floor. When a creature moves onto the lid, it swings open like a trapdoor, causing the creature to fall into the pit, which has sharpened wooden or metal spikes at the bottom. The lid remains open thereafter.\n\nA creature that falls into the pit lands at the bottom and takes 3 (1d6) Bludgeoning damage from the fall plus 9 (2d8) Piercing damage from the spikes.\n\nDetect and Disarm. As a Study action, a creature can examine the section of floor that forms the pit's lid and make a DC 15 Intelligence (Investigation) check, detecting the pit on a successful check. Once the hidden pit is detected, an Iron Spike or a similar object can be wedged between the pit's lid and the surrounding floor to prevent the lid from opening, thereby making it safe to cross. The cover can also be held shut using an Arcane Lock spell or similar magic.\n\nEscape. A creature needs a Climb Speed, climbing gear, or magic such as a Spider Climb spell to scale the pit's smooth walls. You can make the pit easier to escape by adding cracks in the walls big enough to serve as handholds and footholds.\n\nAt Higher Levels. You can scale the trap for higher levels by increasing the pit's depth and damage, as shown in the following table.\n\nLevels 5–10\n\n11–16\n\n17–20\n\nPit Depth 30 feet\n\n60 feet\n\n120 feet\n\nDamage 10 (3d6) Bludgeoning plus 13 (3d8) Piercing\n\n21 (6d6) Bludgeoning plus 36 (8d8) Piercing\n\n42 (12d6) Bludgeoning plus 57 (13d8) Piercing"},
  {"id": "toolbox_combat_encounters", "name": "Combat Encounters", "tag": "", "text": "The following features can make a combat encounter more interesting or challenging:\n\nChanges in Elevation. Terrain features that provide a change of elevation (such as stacks of empty crates, ledges, and balconies) reward clever positioning and encourage characters to jump, climb, fly, or teleport.\n\nDefensive Positions. Enemies in hard-to-reach locations or defensive positions force characters who normally attack at range to move around.\n\nMixed Monster Groups. When different types of monsters work together, they can combine their abilities--just like characters with different classes and origins. A diverse force is more powerful.\n\nReasons to Move. Use features that encourage characters and their enemies to move around, such as chandeliers, kegs of gunpowder or oil, and rolling stone traps."},
  {"id": "toolbox_combat_encounter_difficulty", "name": "Combat Encounter Difficulty", "tag": "", "text": "Use the following guidelines to create a combat encounter of a desired level of difficulty."},
  {"id": "toolbox_step_1_choose_a_difficulty", "name": "Step 1: Choose a Difficulty", "tag": "", "text": "Three categories describe the range of encounter difficulty:\n\nLow Difficulty. An encounter of low difficulty is likely to have one or two scary moments for the players, but their characters should emerge victorious with no casualties. One or more of them might need to use healing resources, however. As a rough guideline, a single monster generally presents a low-difficulty challenge for a party of four characters whose level equals the monster's Challenge Rating.\n\nModerate Difficulty. Absent healing and other resources, an encounter of moderate difficulty could go badly for the adventurers. Weaker characters might get taken out of the fight, and there's a slim chance that one or more characters might die.\n\nHigh Difficulty. A high-difficulty encounter could be lethal for one or more characters. To survive it, the characters will need smart tactics, quick thinking, and maybe even a little luck."},
  {"id": "toolbox_step_2_determine_your_xp_budget", "name": "Step 2: Determine Your XP Budget", "tag": "", "text": "Using the XP Budget per Character table, cross-reference the party's level with the desired encounter difficulty. Multiply the number in the table by the number of characters in the party to get your XP budget for the encounter.\n\nXP Budget per Character\n\nParty's Level\n\n------ Encounter Difficulty ------\n\nLow\n\nModerate\n\nHigh\n\n1,100\n\n1,000\n\n1,400\n\n1,300\n\n1,700\n\n1,000\n\n1,700\n\n2,100\n\n1,300\n\n2,000\n\n2,600\n\n1,600\n\n2,300\n\n3,100\n\n1,900\n\n2,900\n\n4,100\n\n2,200\n\n3,700\n\n4,700\n\n2,600\n\n4,200\n\n5,400\n\n2,900\n\n4,900\n\n6,200\n\n3,300\n\n5,400\n\n7,800\n\n3,800\n\n6,100\n\n9,800\n\n4,500\n\n7,200\n\n11,700\n\n5,000\n\n8,700\n\n14,200\n\n5,500\n\n10,700\n\n17,200\n\n6,400\n\n13,200\n\n22,000"},
  {"id": "toolbox_step_3_spend_your_budget", "name": "Step 3: Spend Your Budget", "tag": "", "text": "Every creature has an XP value in its stat block. When you add a creature to your combat encounter, deduct its XP from your XP budget to determine how many XP you have left to spend. Spend as much of your XP budget as you can without going over. It's OK if you have a few unspent XP left over. Examples are given below:\n\nExample 1. A low-difficulty encounter for four level 1 characters has an XP budget of 50 × 4, for a total of 200 XP. With that, you could build any of the following encounters:\n\n– 1 Bugbear Warrior (200 XP) – 2 Giant Wasps (100 XP each), for 200 XP total – 6 Giant Rats (25 XP each), for 150 XP total\n\nExample 2. A moderate-difficulty encounter for five level 3 characters has an XP budget of 225 × 5, for a total of 1,125 XP. With that, you could build either of these encounters:\n\n– 2 Druids (450 XP each) and 9 Stirges (25 XP each), for 1,125 XP total\n\n– 1 Wight (700 XP), 1 Warhorse Skeleton (100 XP), and 6 Skeletons (50 XP each), for 1,100 XP total\n\nExample 3. A high-difficulty encounter for six level 15 characters has an XP budget of 7,800 × 6, for a total of 46,800 XP. With that, you could build this encounter:\n\n– 2 Adult Red Dragons (18,000 XP each) and 2 Fire Giants (5,000 XP each), for 46,000 XP total"},
  {"id": "toolbox_troubleshooting", "name": "Troubleshooting", "tag": "", "text": "When creating and running combat encounters, keep the following in mind."},
  {"id": "toolbox_many_creatures", "name": "Many Creatures", "tag": "", "text": "The more creatures in an encounter, the higher the risk that a lucky streak on their part could deal more damage to the characters than you expect. If your encounter includes more than two creatures per character, include fragile creatures that can be defeated quickly. This guideline is especially important for characters of level 1 or 2."},
  {"id": "toolbox_adjustments", "name": "Adjustments", "tag": "", "text": "A player's absence might warrant removing creatures from an encounter to keep it at the intended difficulty. Also, die rolls and other factors can result in an encounter being easier or harder than intended. You can adjust an encounter on the fly, such as by having creatures flee (making the encounter easier) or adding reinforcements (making the encounter harder)."},
  {"id": "toolbox_cr_0_creatures", "name": "CR 0 Creatures", "tag": "", "text": "Creatures that have a CR of 0, particularly ones that are worth 0 XP, should be used sparingly. If you want to include many CR 0 critters in an encounter, use swarms instead."},
  {"id": "toolbox_number_of_stat_blocks", "name": "Number of Stat Blocks", "tag": "", "text": "The best combat encounters often pair one kind of creature with another, such as fire giants paired with hell hounds. Be mindful of the number of stat blocks you need to run the encounter. Referencing more than two or three stat blocks for a single encounter can be daunting, particularly if the creatures are complex."},
  {"id": "toolbox_powerful_creatures", "name": "Powerful Creatures", "tag": "", "text": "If your combat encounter includes a creature whose CR is higher than the party's level, be aware that such a creature might deal enough damage with a single action to take out one or more characters. For example, an Ogre (CR 2) can kill a level 1 Wizard with a single blow."},
  {"id": "toolbox_unusual_features", "name": "Unusual Features", "tag": "", "text": "If a monster has a feature that lower-level characters can't easily overcome, consider not adding that monster to an encounter for characters whose level is lower than the monster's Challenge Rating."},
];

export const EQUIPMENT_RULES_2024: RuleEntry[] = [
  {"id": "equipment_coins", "name": "Coins", "tag": "", "text": "Characters often find coins on their adventures and can spend those coins in shops, inns, and other businesses. Coins come in different denominations based on the relative worth of their material. The Coin Values table lists coins and how much they're worth relative to the Gold Piece, which is the game's main coin. For example, 100 Copper Pieces are worth 1 Gold Piece.\n\nA coin weighs about a third of an ounce, so fifty coins weigh a pound.\n\nCoin Values\n\nCoin Copper Piece (CP) Silver Piece (SP) Electrum Piece (EP) Gold Piece (GP) Platinum Piece (PP)\n\nValue in GP 1/100 1/10 1/2 1 10"},
  {"id": "equipment_lifestyle_expenses", "name": "Lifestyle Expenses", "tag": "", "text": "Lifestyle expenses summarize the cost of living in a fantasy world. They cover lodging, food, equipment maintenance, and other necessities.\n\nAt the start of each week or month (GM's choice), choose a lifestyle below--Wretched, Squalid, Poor, Modest, Comfortable, Wealthy, or Aristocratic--and pay the price to sustain that lifestyle.\n\nLifestyles have no inherent consequences, but the GM might take them into account when determining risks or how others perceive your character."},
  {"id": "equipment_wretched_free", "name": "Wretched (Free)", "tag": "", "text": "You survive via chance and charity. You're often exposed to natural dangers as a result of sleeping outside."},
  {"id": "equipment_squalid_1_sp_per_day", "name": "Squalid (1 SP per Day)", "tag": "", "text": "You spend the bare minimum for your necessities. You might be exposed to unhealthy conditions and opportunistic criminals."},
  {"id": "equipment_poor_2_sp_per_day", "name": "Poor (2 SP per Day)", "tag": "", "text": "You spend frugally for your necessities."},
  {"id": "equipment_modest_1_gp_per_day", "name": "Modest (1 GP per Day)", "tag": "", "text": "You support yourself at an average level."},
  {"id": "equipment_comfortable_2_gp_per_day", "name": "Comfortable (2 GP per Day)", "tag": "", "text": "You spend modestly for your necessities and enjoy a few luxuries."},
  {"id": "equipment_wealthy_4_gp_per_day", "name": "Wealthy (4 GP per Day)", "tag": "", "text": "You're accustomed to the finer things in life and might have servants.\n\nAristocratic (10 GP per Day)\n\nYou pay for the best and might have a staff that supports your lifestyle. Others notice your wealth and might encourage you to share it, either legally or otherwise."},
  {"id": "equipment_food_drink_and_lodging", "name": "Food, Drink, and Lodging", "tag": "", "text": "The Food, Drink, and Lodging table gives prices for food and a single night's lodging. Prices for daily lodging and meals are included in your lifestyle's expenses.\n\nFood, Drink, and Lodging\n\nItem\n\nCost Item\n\nAle (mug)\n\n4 CP Comfortable\n\nBread (loaf)\n\n2 CP Wealthy\n\nCheese (wedge) 1 SP Aristocratic\n\nInn Stay per Day\n\nMeal\n\nSqualid\n\n7 CP Squalid\n\nPoor\n\n1 SP Poor\n\nModest\n\n5 SP Modest\n\nCost 8 SP 2 GP 4 GP\n\n1 CP 2 CP 1 SP\n\nItem Comfortable Wealthy Aristocratic\n\nCost 2 SP 3 SP 6 SP\n\nItem Wine (bottle)\n\nCommon Fine\n\nCost\n\n2 SP 10 GP\n\nHirelings\n\nSkilled hirelings include anyone hired to perform a service that involves a proficiency (including weapon, tool, or skill): a mercenary, an artisan, a scribe, or the like. The pay shown on the Hirelings table is a minimum; some expert hirelings require more pay. Untrained hirelings are hired for work that requires no particular proficiencies; they include laborers and porters.\n\nHirelings\n\nService Skilled hireling Untrained hireling Messenger\n\nCost 2 GP per day 2 SP per day 2 CP per mile"},
  {"id": "equipment_spellcasting", "name": "Spellcasting", "tag": "", "text": "Most settlements contain individuals who are willing to cast spells in exchange for payment. If a spell has expensive components, add the cost of those components to the cost listed in the Spellcasting Services table. The higher the level of a desired spell, the harder it is to find someone to cast it.\n\nSpellcasting Services\n\nSpell Level Availability\n\nCantrip Village, town, or city\n\nVillage, town, or city\n\nVillage, town, or city\n\nTown or city only\n\n4–5\n\nTown or city only\n\n6–8\n\nCity only\n\nCity only\n\nCost 30 GP 50 GP 200 GP 300 GP 2,000 GP 20,000 GP 100,000 GP"},
  {"id": "equipment_magic_items", "name": "Magic Items", "tag": "", "text": "Adventures hold the promise--but not a guarantee--of finding magic items. Hundreds of magic items are detailed in \"Magic Items\" later in this document. Here's what you need to know about using magic items."},
  {"id": "equipment_identifying_a_magic_item", "name": "Identifying a Magic Item", "tag": "", "text": "Some magic items are indistinguishable from their nonmagical counterparts, while others are conspicuously magical. Handling a magic item is enough to\n\ngive you a sense that it is extraordinary, but learning a magic item's properties isn't automatic.\n\nThe Identify spell is the fastest way to reveal an item's properties. Alternatively, you can focus on one magic item during a Short Rest while being in physical contact with the item. At the end of the rest, you learn its properties and how to use them (but not any curse the item might bear).\n\nSometimes a magic item carries a clue to its properties. The command word to activate a ring might be etched inside the band, or a feathered design might hint that it's a Ring of Feather Falling.\n\nWearing or experimenting with an item can also offer hints about its properties. In the specific case of Potions, a little taste is enough to tell the taster what a potion does. Other items might require more experimentation. For example, if your character puts on a Ring of Swimming, the GM might say, \"Your movement feels strangely fluid.\" Perhaps you then dive into a river to see what happens. The GM would then say you swim unexpectedly well."},
  {"id": "equipment_attunement", "name": "Attunement", "tag": "", "text": "Some magic items require a creature to form a bond--called Attunement--with them before the creature can use an item's magical properties. Without becoming attuned to an item that requires Attunement, you gain only its nonmagical benefits unless its description states otherwise. For example, a magic Shield that requires Attunement provides the benefits of a normal Shield if you aren't attuned to it, but none of its magical properties."},
  {"id": "equipment_attune_during_a_short_rest", "name": "Attune during a Short Rest", "tag": "", "text": "Attuning to an item requires you to spend a Short Rest focused on only that item while being in physical contact with it (this can't be the same Short Rest used to learn the item's properties). This focus can take the form of weapon practice (for a Weapon), meditation (for a Wand), or some other appropriate activity. If the Short Rest is interrupted, the Attunement attempt fails. Otherwise, at the end of the Short Rest, you're attuned to the magic item and can access its full magical capabilities."},
  {"id": "equipment_no_more_than_three_items", "name": "No More Than Three Items", "tag": "", "text": "You can be attuned to no more than three magic items at a time. Any attempt to attune to a fourth item fails; you must end your Attunement to an item first. Additionally, you can't attune to more than one copy of an item. For example, you can't attune to more than one Ring of Protection at a time."},
  {"id": "equipment_ending_attunement", "name": "Ending Attunement", "tag": "", "text": "Your Attunement to an item ends if you no longer satisfy the prerequisites for Attunement, if the item has been more than 100 feet away for at least 24 hours, if you die, or if another creature attunes to\n\nthe item. You can also voluntarily end Attunement by spending another Short Rest focused on the item unless the item is cursed."},
  {"id": "equipment_wearing_and_wielding_items", "name": "Wearing and Wielding Items", "tag": "", "text": "Using a magic item's properties might mean wearing or wielding it. A magic item meant to be worn must be donned in the intended fashion: boots go on feet, gloves on hands, hats and helmets on a head, and rings on a finger. Magic armor must be donned, a Shield strapped to the arm, a cloak fastened about the shoulders. A weapon must be held.\n\nIn most cases, a magic item that's meant to be worn can fit a creature regardless of size or build. Magic garments are made to be easily adjustable, or they magically adjust themselves to the wearer."},
  {"id": "equipment_multiple_items_of_the_same_kind", "name": "Multiple Items of the Same Kind", "tag": "", "text": "You can't wear more than one of certain magic items. You can't normally wear more than one pair of footwear, one pair of gloves or gauntlets, one pair of bracers, one suit of armor, one item of headwear, or one cloak. The GM might make exceptions."},
  {"id": "equipment_paired_items", "name": "Paired Items", "tag": "", "text": "Items that come in pairs--such as boots, bracers, gauntlets, and gloves--impart their benefits only if both items of the pair are worn. For example, a character wearing a Boot of Striding and Springing on one foot and a Boot of Elvenkind on the other foot gains no benefit from either."},
  {"id": "equipment_crafting_nonmagical_items", "name": "Crafting Nonmagical Items", "tag": "", "text": "To craft a nonmagical item, you need tools, raw materials, and time, each of which is detailed below. If you meet the requirements, you make the item, and you can use it or sell it at its normal price."},
  {"id": "equipment_tools", "name": "Tools", "tag": "", "text": "The \"Tools\" section of \"Equipment\" lists which tools are required to make certain items. The GM assigns required tools for items not listed there.\n\nYou must use the required tool to make an item and have proficiency with that tool. Anyone who helps you must also have proficiency with it."},
  {"id": "equipment_raw_materials", "name": "Raw Materials", "tag": "", "text": "To make an item, you need raw materials worth half its purchase cost (round down). For example, you need 750 GP of raw materials to make Plate Armor, which sells for 1,500 GP. The GM determines whether appropriate raw materials are available."},
  {"id": "equipment_time", "name": "Time", "tag": "", "text": "To determine how many days (working 8 hours a day) it takes to make an item, divide its purchase cost in GP by 10 (round a fraction up to a day). For\n\nexample, you need 5 days to make a Heavy Crossbow, which sells for 50 GP.\n\nIf an item requires multiple days, the days needn't be consecutive.\n\nCharacters can combine their efforts to shorten the crafting time. Divide the time needed to create an item by the number of characters working on it. Normally, only one other character can assist you, but the GM might allow more assistants."},
  {"id": "equipment_brewing_potions_of_healing", "name": "Brewing Potions of Healing", "tag": "", "text": "A character who has proficiency with the Herbalism Kit can create a Potion of Healing. Doing so requires using that kit and 25 GP of raw material over the course of 1 day (8 hours of work)."},
  {"id": "equipment_scribing_spell_scrolls", "name": "Scribing Spell Scrolls", "tag": "", "text": "A spellcaster can transfer a spell to a scroll and create a Spell Scroll, using the rules below."},
  {"id": "equipment_time_and_cost", "name": "Time and Cost", "tag": "", "text": "Scribing a scroll takes an amount of time and money based on the level of the spell, as shown in the Spell Scroll Costs table. For each day of inscription, you must work for 8 hours. If a scroll requires multiple days, those days needn't be consecutive."},
  {"id": "equipment_prerequisites_for_the_scribe", "name": "Prerequisites for the Scribe", "tag": "", "text": "To scribe a scroll, you must have proficiency in the Arcana skill or with Calligrapher's Supplies and have the spell prepared on each day of the inscription. You must also have at hand any Material components required by the spell; if the spell consumes its Material components, they are consumed only when you complete the scroll. The scroll's spell uses your spell save DC and spell attack bonus."},
  {"id": "equipment_cantrips", "name": "Cantrips", "tag": "", "text": "If the scribed spell is a cantrip, the version on the scroll works as if the caster were your level.\n\nSpell Scroll Costs\n\nSpell Level\n\nTime\n\nCantrip\n\n1 day\n\n1 day\n\n3 days\n\n5 days\n\n10 days\n\n25 days\n\n40 days\n\n50 days\n\n60 days\n\n120 days\n\nCost 15 GP 25 GP 100 GP 150 GP 1,000 GP 1,500 GP 10,000 GP 12,500 GP 15,000 GP 50,000 GP"},
];
